window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"module":"yiliao","prompt":"推拿的适应证不包括","options":["腰肌劳损","颈椎病","骨折早期","小儿腹泻"],"answer":2,"explanation":"骨折早期为推拿禁忌，以免加重损伤。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2501","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“治未病”思想是指","options":["只防不治","只治已病","不治病","未病先防，既病防变"],"answer":3,"explanation":"治未病包括未病先防和既病防变两方面。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2502","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医养生的基本原则不包括","options":["起居有常","顺应自然","过度劳累","饮食有节"],"answer":2,"explanation":"养生强调顺应自然、起居有常、饮食有节、劳逸适度，过度劳累违背养生原则。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2503","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“精”的概念是指","options":["仅指水谷之精","仅指生殖之精","构成人体和维持生命活动的基本物质","仅指血液"],"answer":2,"explanation":"精是构成人体、维持生命活动的基本物质，包括先天之精和后天之精。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2504","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“神”的产生基础是","options":["津液","血液","精气","营气"],"answer":2,"explanation":"神以精为基础，精化气，气化神。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2505","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“津液”的功能不包括","options":["产生津液","化生血液","运输营养物质","濡养脏腑"],"answer":3,"explanation":"津液有濡养、化血、运输等功能，本身不产生津液。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2506","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“气”的功能不包括","options":["温煦","固摄","气化","凝固"],"answer":0,"explanation":"气的功能包括推动、温煦、防御、固摄、气化，无“凝固”功能。","exam":"医疗编","__sub":"中医基础","diff":2,"id":"yl-2507","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“气化”是指","options":["气的固摄","气的升降","气的出入","气的运动产生的各种变化"],"answer":3,"explanation":"气化指气的运动（升降出入）产生的各种变化，如物质转化。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2508","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“宗气”的生成来源是","options":["自然界的清气和脾胃化生的水谷精气","先天之精","肾气","卫气"],"answer":0,"explanation":"宗气由肺吸入的清气与脾胃化生的水谷精气结合而成。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2509","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“卫气”的主要功能是","options":["化生血液","推动血液运行","护卫肌表，温养脏腑，调节汗孔开合","固摄精液"],"answer":2,"explanation":"卫气行于脉外，护卫肌表、温养脏腑、调节汗孔开合。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2510","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“营气”的主要功能是","options":["化生血液，营养全身","护卫肌表","调节汗孔","推动气血"],"answer":0,"explanation":"营气行于脉中，化生血液、营养全身。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2511","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“血府”是指","options":["肝","心","脉","脾"],"answer":2,"explanation":"脉为血之府，血液运行之通道。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2512","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“娇脏”是指","options":["肝","肺","脾","肾"],"answer":1,"explanation":"肺为娇脏，清虚娇嫩，易受外邪侵袭。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2513","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“刚脏”是指","options":["肺","肝","心","脾"],"answer":1,"explanation":"肝为刚脏，主升主动，体阴用阳。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2514","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“胃”的生理功能是","options":["输布精微","运化水谷","受纳腐熟水谷","排泄尿液"],"answer":2,"explanation":"胃主受纳腐熟水谷，为水谷之海。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2515","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“小肠”的主要生理功能是","options":["传导糟粕","受纳腐熟","运化水液","受盛化物，泌别清浊"],"answer":3,"explanation":"小肠受盛化物、泌别清浊，分清别浊。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2516","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“大肠”的主要生理功能是","options":["受盛化物","传导糟粕","泌别清浊","运化水谷"],"answer":1,"explanation":"大肠主传导糟粕，将食物残渣形成粪便排出。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2517","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“膀胱”的主要生理功能是","options":["输布津液","受纳水谷","化生尿液","贮尿和排尿"],"answer":3,"explanation":"膀胱主贮尿和排尿，依赖肾阳气化。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2518","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“三焦”的概念是","options":["一个穴位","一个脏腑","上焦、中焦、下焦的合称","一种病名"],"answer":2,"explanation":"三焦为六腑之一，为上中下三焦的合称，主通行元气和水液。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2519","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“心主血脉”是指","options":["心气推动血液在脉中运行","心化生血液","心藏神","心开窍于舌"],"answer":0,"explanation":"心主血脉包括主血和主脉两方面，心气推动血液运行。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2520","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中医“肝藏血”是指","options":["肝行血","肝化生血液","肝统血","肝具有贮藏血液和调节血量的功能"],"answer":3,"explanation":"肝藏血包括贮藏血液、调节血量、防止出血等。","exam":"医疗编","__sub":"中医基础","diff":1,"id":"yl-2521","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"流行病学研究的对象是","options":["单个病人","人群","动物","细胞"],"answer":1,"explanation":"流行病学以人群为研究对象，研究疾病、健康状态的分布及影响因素。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2522","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"流行病学研究中最基本的方法是","options":["数学模型法","实验法","观察法","访谈法"],"answer":2,"explanation":"流行病学以观察法为最基本方法，包括描述性和分析性研究。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2523","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"描述疾病流行强度的术语不包括","options":["流行","暴发","散发","转归"],"answer":2,"explanation":"疾病流行强度分为散发、暴发、流行和大流行，转归为疾病结局。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2524","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"某病发病率呈历年一般水平称为","options":["大流行","暴发","散发","聚集性"],"answer":2,"explanation":"散发指发病率呈历年一般水平，病例间无明显联系。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2525","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"表示疾病发生强度的指标是","options":["发病率","患病率","死亡率","病死率"],"answer":0,"explanation":"发病率反映疾病新发病例发生的强度。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2526","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"患病率是指","options":["某病死亡数","某期间新发病例数","某特定时间内某病新旧病例数占同期平均人口数的比例","某病治愈数"],"answer":2,"explanation":"患病率=某时期新旧病例总数/同期平均人口数，反映患病总量。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2527","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"发病率与患病率的关系是","options":["患病率取决于发病率和病程","患病率仅取决于发病率","二者无关","发病率取决于患病率"],"answer":0,"explanation":"患病率≈发病率×病程，病程长则患病率高。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2528","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"某病病死率是指","options":["该病患者中死于该病的比例","该病死亡数占人口比例","该病治愈比例","该病复发比例"],"answer":0,"explanation":"病死率=死于某病的例数/该病患病总例数，反映疾病严重程度。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2529","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"死亡率是指","options":["某病死亡比例","某期间死于所有原因的人数占同期平均人口数的比例","婴儿死亡比例","意外死亡比例"],"answer":1,"explanation":"死亡率=同期死亡总人数/同期平均人口数，为全死因死亡强度指标。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2530","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"反映疾病治疗效果的近期指标是","options":["发病率","治愈率","患病率","死亡率"],"answer":1,"explanation":"治愈率、有效率等反映疾病近期治疗效果。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2531","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"队列研究的性质是","options":["前瞻性（由因到果）","回顾性（由果到因）","横断面","个案调查"],"answer":0,"explanation":"队列研究按暴露与否分组，前瞻性追踪结局，由因到果。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2532","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"病例对照研究的性质是","options":["实验性","前瞻性","回顾性（由果到因）","干预性"],"answer":2,"explanation":"病例对照研究以病例和对照为对象，回顾暴露史，由果到因。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2533","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"病例对照研究中最主要的偏倚是","options":["失访偏倚","回忆偏倚","测量偏倚","混杂偏倚"],"answer":1,"explanation":"病例对照研究需回忆暴露史，易发生回忆偏倚。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2534","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"衡量某因素与疾病关联强度的指标是","options":["相对危险度（RR）","发病率","死亡率","患病率"],"answer":0,"explanation":"RR为暴露组与非暴露组发病率之比，反映关联强度。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2535","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"RR值大于1说明","options":["无法判断","呈负相关","无关联","暴露因素与疾病呈正相关（危险因素）"],"answer":3,"explanation":"RR>1表示暴露增加疾病风险，为危险因素；RR<1为保护因素。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2536","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"队列研究中常见的偏倚是","options":["测量偏倚","回忆偏倚","选择偏倚","失访偏倚"],"answer":3,"explanation":"队列研究随访时间长，失访偏倚最常见。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2537","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"实验流行病学与观察性研究的根本区别是","options":["样本大小","是否人为施加干预","研究时间","研究对象"],"answer":1,"explanation":"实验研究由研究者人为施加干预措施，观察性研究不施加干预。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2538","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"临床试验中，随机分组的目的是","options":["增加样本量","平衡两组的混杂因素","减少费用","方便操作"],"answer":1,"explanation":"随机化使已知和未知的混杂因素在组间均衡分布。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2539","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"临床试验中双盲是指","options":["研究者和受试者均不知分组情况","仅受试者不知","仅研究者不知","统计分析者不知"],"answer":0,"explanation":"双盲指研究者和受试者均不知分组情况，减少偏倚。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2540","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"筛检试验的目的是","options":["从外表健康者中查出可能患某病的人","确诊疾病","治疗疾病","预防疾病"],"answer":0,"explanation":"筛检是运用快速简便的试验从外表健康人群中找出可疑患病者。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2541","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"筛检试验中，灵敏度是指","options":["实际无病者中被筛检为阴性的比例","实际有病者中被筛检为阳性的比例","筛检阳性者中患病的比例","筛检阴性者中无病的比例"],"answer":1,"explanation":"灵敏度=真阳性/(真阳性+假阴性)，反映发现病人的能力。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2542","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"筛检试验中，特异度是指","options":["筛检阳性者中患病的比例","实际有病者中被筛检为阳性的比例","实际无病者中被筛检为阴性的比例","筛检阴性者中患病的比例"],"answer":2,"explanation":"特异度=真阴性/(真阴性+假阳性)，反映排除非病人的能力。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2543","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"提高筛检试验灵敏度的结果是","options":["准确性提高","假阴性增加","假阳性减少","假阴性减少，假阳性增加"],"answer":3,"explanation":"灵敏度提高时更多病人被检出，假阴性减少，但假阳性可能增加。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2544","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"评价筛检试验真实性的指标是","options":["灵敏度和特异度","阳性预测值","阴性预测值","可靠性"],"answer":0,"explanation":"灵敏度和特异度反映试验的真实性；可靠性反映重复性。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2545","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"传染病的流行过程必须具备的三个环节是","options":["传染源、传播途径、易感人群","病原体、宿主、环境","症状、体征、化验","潜伏期、前驱期、恢复期"],"answer":0,"explanation":"传染病流行需传染源、传播途径、易感人群三环节同时存在。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2546","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"传染源是指","options":["体内有病原体生长繁殖并能排出病原体的人和动物","病原体携带者","易感者","康复者"],"answer":0,"explanation":"传染源包括病人、病原携带者和受感染的动物。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2547","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"经空气传播的传染病，其流行特征是","options":["呈食物型暴发","夏季高发","冬春季高发，儿童多见","接触传播为主"],"answer":2,"explanation":"空气传播传染病多见于冬春季，儿童发病率高，传播广泛。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2548","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"经水传播的传染病，其流行特征是","options":["病例分布与供水范围一致，可呈暴发","冬春季高发","仅散发","与接触有关"],"answer":0,"explanation":"经水传播常呈暴发或流行，病例集中于供水范围。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2549","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"潜伏期是指","options":["病原体侵入机体至出现临床症状的这段时间","发病至痊愈的时间","传染期","恢复期"],"answer":0,"explanation":"潜伏期为病原体侵入至首发症状的时间，用于确定检疫期。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2550","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"确定传染病检疫期的重要依据是","options":["潜伏期","前驱期","恢复期","传染期"],"answer":0,"explanation":"检疫期按该病最长潜伏期确定。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2551","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"预防传染病最有效的措施是","options":["仅消毒","仅隔离","针对流行三环节的综合措施","仅治疗"],"answer":2,"explanation":"传染病防控采取管理传染源、切断传播途径、保护易感人群的综合措施。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2552","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"人工主动免疫是","options":["接种疫苗使机体产生特异性免疫","注射免疫球蛋白","注射抗生素","输血"],"answer":0,"explanation":"人工主动免疫通过接种疫苗刺激机体产生抗体和细胞免疫。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2553","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"人工被动免疫是","options":["接种疫苗","注射免疫球蛋白或抗毒素使机体立即获得免疫力","口服疫苗","自然感染"],"answer":1,"explanation":"人工被动免疫注射现成抗体，起效快但维持时间短。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2554","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"我国计划免疫（免疫规划）的疫苗不包括","options":["乙肝疫苗","卡介苗","流感疫苗","脊灰疫苗"],"answer":2,"explanation":"国家免疫规划疫苗包括卡介苗、乙肝、脊灰、百白破、麻疹等，流感为自费非规划疫苗。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2555","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"新生儿出生后24小时内应接种的疫苗是","options":["乙肝疫苗和卡介苗","麻疹疫苗","百白破疫苗","脊灰疫苗"],"answer":0,"explanation":"新生儿24小时内接种乙肝疫苗第1剂和卡介苗。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2556","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"我国法定传染病分为","options":["甲、乙两类","甲、乙、丙三类","甲、乙、丙、丁四类","仅甲类"],"answer":1,"explanation":"法定传染病分甲类（2种）、乙类、丙类。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2557","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"属于甲类传染病的是","options":["艾滋病","霍乱","麻疹","伤寒"],"answer":1,"explanation":"甲类传染病为鼠疫和霍乱，实行强制管理。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2558","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"发现甲类传染病病人，报告时限为","options":["2小时内","12小时内","24小时内","48小时内"],"answer":0,"explanation":"甲类传染病及乙类中按甲类管理的病种应于2小时内网络直报。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2559","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"发现乙类传染病病人，报告时限为","options":["72小时内","2小时内","48小时内","24小时内"],"answer":3,"explanation":"乙类、丙类传染病应于24小时内网络直报。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2560","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"对甲类传染病病人应采取的措施是","options":["仅随访","居家观察","无需隔离","强制隔离治疗"],"answer":3,"explanation":"甲类传染病病人和病原携带者应予以隔离治疗，隔离期按医学检查结果确定。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2561","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"切断传播途径的主要措施是","options":["预防服药","接种疫苗","隔离病人","消毒、杀虫、改善环境卫生"],"answer":3,"explanation":"切断传播途径以消毒、杀虫和一般卫生措施为主。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2562","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"保护易感人群的主要措施是","options":["预防接种","隔离病人","消毒","杀虫"],"answer":0,"explanation":"预防接种（计划免疫）是保护易感人群的最有效措施。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2563","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"环境污染物对健康的危害不包括","options":["急性危害","慢性危害","远期危害","免疫增强"],"answer":0,"explanation":"环境污染可致急性、慢性及远期危害（致癌、致畸、致突变），不会增强免疫。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2564","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"室内空气污染的主要来源不包括","options":["室外大气污染","建筑材料","燃料燃烧","吸烟"],"answer":0,"explanation":"室内空气污染主要来自建筑材料（氡）、燃料燃烧、吸烟、装修等，室外大气污染非主要来源。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2565","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"饮用水消毒的主要目的是","options":["软化水质","去除异味","去除重金属","杀灭水中的病原微生物"],"answer":3,"explanation":"饮用水消毒以杀灭病原微生物、防止介水传染病为目的。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2566","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"我国生活饮用水卫生标准规定，管网末梢水中游离性余氯不应低于","options":["0.05mg/L","0.5mg/L","0.3mg/L","1mg/L"],"answer":0,"explanation":"出厂水游离氯≥0.3mg/L，管网末梢水≥0.05mg/L。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2567","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"食物中毒的特点不包括","options":["潜伏期短","传染性","同食者集体发病","症状相似"],"answer":1,"explanation":"食物中毒无传染性，呈暴发、症状相似、停止食用后不再发病。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2568","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"细菌性食物中毒的主要表现是","options":["急性胃肠炎症状","神经系统症状","皮疹","关节痛"],"answer":0,"explanation":"细菌性食物中毒以急性胃肠炎症状为主，如恶心、呕吐、腹痛、腹泻。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2569","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"沙门菌食物中毒的常见食品是","options":["肉类及其制品","水果","蔬菜","谷物"],"answer":0,"explanation":"沙门菌食物中毒多由肉、蛋、奶及其制品引起。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2570","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"副溶血性弧菌食物中毒的常见食品是","options":["豆制品","谷物","海产品","乳制品"],"answer":2,"explanation":"副溶血性弧菌嗜盐，常见于海产品及盐腌食品。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2571","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"河豚鱼中毒的主要表现是","options":["胃肠炎症状","神经系统症状（口唇麻木、四肢无力）","皮疹","发热"],"answer":1,"explanation":"河豚毒素主要损害神经系统，表现为口唇麻木、四肢无力、呼吸困难。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2572","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"亚硝酸盐中毒的特效解毒剂是","options":["阿托品","亚甲蓝","解磷定","纳洛酮"],"answer":1,"explanation":"亚硝酸盐中毒致高铁血红蛋白血症，用亚甲蓝（美蓝）解救。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2573","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"有机磷农药中毒的特效解毒剂是","options":["地塞米松","亚甲蓝","纳洛酮","阿托品和解磷定"],"answer":3,"explanation":"有机磷中毒用阿托品对抗毒蕈碱症状，胆碱酯酶复能剂（解磷定）恢复酶活性。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2574","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"一氧化碳中毒的机制是","options":["形成碳氧血红蛋白，导致缺氧","抑制呼吸中枢","损伤肝脏","溶血"],"answer":0,"explanation":"CO与血红蛋白结合形成碳氧血红蛋白，使血红蛋白失去携氧能力。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2575","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"职业病的诊断依据不包括","options":["现场劳动卫生调查","职业史","病人的主观意愿","临床表现与实验室检查"],"answer":2,"explanation":"职业病诊断依据职业史、现场调查、临床表现及实验室检查，不依据主观意愿。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2576","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"我国法定职业病报告制度要求","options":["不报告","确诊后按规定报告","仅口头报告","延迟报告"],"answer":1,"explanation":"职业病确诊后应按规定时限报告，实行网络直报。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2577","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"尘肺病的主要预防措施是","options":["仅通风","仅戴口罩","湿式作业、密闭尘源、个体防护","仅体检"],"answer":2,"explanation":"尘肺预防采取湿式作业、密闭尘源、通风除尘、个体防护等综合措施。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2578","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"噪声对人体的主要危害是","options":["贫血","消化性溃疡","皮肤病","听力损伤"],"answer":3,"explanation":"长期噪声暴露致听力下降，严重者噪声性耳聋。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2579","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"生产性毒物进入人体的主要途径是","options":["呼吸道","消化道","皮肤","眼睛"],"answer":0,"explanation":"生产性毒物以呼吸道吸入为主要进入途径。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2580","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"铅中毒的典型表现是","options":["皮疹","腹绞痛、贫血、周围神经炎","发热","关节痛"],"answer":1,"explanation":"慢性铅中毒表现为腹绞痛、贫血、周围神经炎、铅线等。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2581","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"苯中毒的主要危害是","options":["心脏损害","肝脏损害","肾脏损害","造血系统损害（白细胞减少）"],"answer":3,"explanation":"慢性苯中毒主要损害造血系统，致白细胞减少、再生障碍性贫血。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2582","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"矽肺的致病因素是","options":["棉尘","煤尘","游离二氧化硅粉尘","木尘"],"answer":2,"explanation":"矽肺由长期吸入含游离二氧化硅的粉尘引起。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2583","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"健康的概念是","options":["没有疾病","身体、心理和社会适应的完好状态，而不仅是没有疾病","体格强壮","心理正常"],"answer":1,"explanation":"WHO定义健康为身体、心理和社会适应的完好状态。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2584","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"影响健康的主要因素不包括","options":["行为生活方式","环境因素","医疗技术","生物遗传因素"],"answer":2,"explanation":"影响健康的四大因素为环境、行为生活方式、生物遗传和医疗卫生服务，医疗技术非主要因素。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2585","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"健康促进的三大策略是","options":["倡导、赋权、协调","宣传、教育、治疗","预防、治疗、康复","管理、监督、评价"],"answer":0,"explanation":"健康促进三大策略为倡导（advocacy）、赋权（enable）、协调（mediation）。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2586","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"健康教育的核心是","options":["体检","宣传疾病知识","发放宣传资料","促使人们改变不良行为和生活方式"],"answer":3,"explanation":"健康教育以行为干预为核心，促使人们建立健康行为。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2587","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"初级卫生保健的基本内容不包括","options":["疾病预防","健康教育","专科治疗","基本治疗"],"answer":2,"explanation":"初级卫生保健包括健康教育、预防接种、基本医疗等，不包括专科治疗。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2588","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"我国卫生工作的方针是","options":["以专科为重点","以治疗为中心","以城市为中心","以基层为重点，以改革创新为动力，预防为主，中西医并重"],"answer":3,"explanation":"新时代卫生与健康工作方针：以基层为重点，以改革创新为动力，预防为主，中西医并重，将健康融入所有政策，人民共建共享。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2589","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"三级预防中的第二级预防是指","options":["临床预防","病因预防","康复预防","“三早”预防（早发现、早诊断、早治疗）"],"answer":3,"explanation":"第一级预防为病因预防；第二级为“三早”；第三级为临床预防、康复。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2590","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"三级预防中的第一级预防是指","options":["病因预防（针对致病因素）","早发现","早治疗","康复"],"answer":0,"explanation":"第一级预防针对病因和健康促进，是最积极的预防措施。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2591","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"慢性病的主要危险因素不包括","options":["不合理膳食","吸烟","缺乏运动","接种疫苗"],"answer":1,"explanation":"慢性病危险因素包括吸烟、不合理膳食、缺乏运动、过量饮酒等，接种疫苗为保护因素。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2592","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"高血压的主要危险因素是","options":["适量运动","低盐饮食","高盐饮食、超重、精神紧张","戒烟"],"answer":2,"explanation":"高盐饮食、超重肥胖、精神紧张、过量饮酒为高血压主要危险因素。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2593","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"糖尿病的主要危险因素是","options":["运动","肥胖、缺乏运动、遗传","低糖饮食","正常体重"],"answer":1,"explanation":"2型糖尿病主要危险因素为肥胖、缺乏运动、遗传及不合理膳食。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2594","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"吸烟对健康的主要危害不包括","options":["心血管疾病","肺癌","增强免疫力","慢性阻塞性肺疾病"],"answer":2,"explanation":"吸烟是肺癌、心血管疾病、COPD等的重要危险因素，不增强免疫力。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2595","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"过量饮酒对健康的主要危害不包括","options":["肝脏损害","增强记忆力","神经系统损害","消化系统损害"],"answer":1,"explanation":"过量饮酒致肝损害、神经系统损害、消化系统疾病等，不增强记忆力。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2596","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"合理膳食的基本要求不包括","options":["高盐高脂","食物多样","荤素搭配","适量摄入"],"answer":0,"explanation":"合理膳食要求食物多样、荤素搭配、适量摄入、低盐低脂。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2597","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中国居民膳食指南建议成人每日食盐摄入量不超过","options":["15克","10克","5克","20克"],"answer":2,"explanation":"膳食指南建议成人每日食盐不超过5克，食用油25～30克。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2598","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"中国居民膳食指南建议成人每日添加糖摄入量不超过","options":["100克","50克（最好25克以下）","150克","200克"],"answer":1,"explanation":"每日添加糖不超过50克，最好控制在25克以下。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2599","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"体质指数（BMI）的计算公式是","options":["体重×身高","体重/身高","身高/体重","体重（kg）/身高（m）的平方"],"answer":3,"explanation":"BMI=体重（kg）/[身高（m）]²，18.5～23.9为正常。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2600","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"我国成人超重的BMI标准是","options":["BMI≥30","BMI≥28","24≤BMI<28","BMI≥25"],"answer":2,"explanation":"我国成人：18.5～23.9正常，24～27.9超重，≥28肥胖。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2601","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"有氧运动的主要特点是","options":["高强度短时间","中等强度、有节奏、持续时间较长","无规律","仅力量训练"],"answer":1,"explanation":"有氧运动如快走、慢跑、游泳，中等强度、持续时间较长。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2602","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"建议成人每周进行中等强度运动的时间为","options":["300分钟","30分钟","150分钟以上","600分钟"],"answer":2,"explanation":"WHO建议成人每周至少150分钟中等强度有氧运动。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2603","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"突发公共卫生事件的特点不包括","options":["公共属性","突发性","可预测性","危害严重"],"answer":2,"explanation":"突发公共卫生事件具有突发性、公共属性、危害严重、复杂性等特点，不可预测。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2604","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"突发公共卫生事件应急处理的原则是","options":["隐瞒信息","各自为政","延迟处理","统一领导、分级负责、反应及时、措施果断"],"answer":3,"explanation":"应急处理坚持统一领导、分级负责、反应及时、措施果断、依靠科学、加强合作。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2605","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"突发公共卫生事件报告的时限为","options":["24小时内","2小时内","12小时内","48小时内"],"answer":1,"explanation":"较大以上突发事件应在2小时内报告。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2606","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"消毒的目的不包括","options":["杀灭或清除传播媒介上的病原微生物","增强人体免疫力","预防感染","控制疫情"],"answer":1,"explanation":"消毒针对病原微生物，不增强人体免疫力。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2607","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"疫源地消毒中，随时消毒是指","options":["终末消毒","传染源离开后的消毒","预防性消毒","有传染源存在时对其排出物及污染场所进行的消毒"],"answer":3,"explanation":"随时消毒在传染源存在时进行；终末消毒在传染源离开后进行。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2608","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"杀虫的主要目的是","options":["消灭细菌","消灭老鼠","消灭传播疾病的节肢动物","消灭病毒"],"answer":2,"explanation":"杀虫针对蚊、蝇、蚤等节肢动物，切断虫媒传播途径。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2609","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"灭鼠的主要目的是","options":["消灭昆虫","消灭鼠类传染源和破坏其传播途径","消灭细菌","消灭病毒"],"answer":1,"explanation":"鼠类为多种传染病传染源和媒介，灭鼠属针对传染源和传播途径的措施。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2610","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"地方性甲状腺肿的主要原因是","options":["缺碘","缺钙","缺铁","缺锌"],"answer":0,"explanation":"碘缺乏致地方性甲状腺肿，严重者致克汀病。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2611","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"地方性氟中毒的主要原因是","options":["长期摄入过量氟","缺氟","缺钙","缺硒"],"answer":0,"explanation":"氟中毒致氟斑牙和氟骨症，由饮水或燃煤氟污染引起。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2612","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"克山病的病因与哪种元素缺乏有关","options":["铁","硒","锌","铜"],"answer":1,"explanation":"克山病与缺硒有关，补硒可预防。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2613","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"儿童青少年近视的主要预防措施是","options":["多看书","增加户外活动时间，控制用眼时间","多看电视","不运动"],"answer":1,"explanation":"每天2小时以上户外活动、控制近距离用眼时间是预防近视的有效措施。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2614","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"学校卫生中，教室课桌面照度不应低于","options":["100lx","50lx","300lx","1000lx"],"answer":2,"explanation":"教室课桌面维持平均照度不低于300lx，黑板不低于500lx。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2615","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"老年人健康管理的重点是","options":["仅体检","慢病管理、功能维护、预防跌倒","仅用药","仅运动"],"answer":1,"explanation":"老年人健康管理以慢病管理、功能维护、跌倒预防、心理健康为重点。","exam":"医疗编","__sub":"公共卫生","diff":1,"id":"yl-2616","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"妇幼保健的主要内容不包括","options":["计划生育技术服务","孕产期保健","儿童保健","专科手术"],"answer":3,"explanation":"妇幼保健包括孕产期保健、儿童保健、生殖健康等，不含专科手术。","exam":"医疗编","__sub":"公共卫生","diff":2,"id":"yl-2617","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《中华人民共和国基本医疗卫生与健康促进法》规定，我国医疗卫生事业应当坚持","options":["公益性原则","营利性原则","市场化原则","自由化原则"],"answer":0,"explanation":"医疗卫生事业坚持公益性原则。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2618","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"我国卫生法律体系的核心法律是","options":["《医疗机构管理条例》","《执业医师法》","《中华人民共和国基本医疗卫生与健康促进法》","《药品管理法》"],"answer":2,"explanation":"基本医疗卫生与健康促进法为卫生健康领域基础性、综合性法律。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2619","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师经注册后，可以在医疗卫生机构中","options":["按照注册的执业地点、执业类别、执业范围执业","随意执业","跨类别执业","无限制执业"],"answer":0,"explanation":"医师应按注册的执业地点、类别和范围执业。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2620","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《医师法》规定，医师注册后变更执业地点等事项应","options":["无需变更","办理变更注册手续","重新考试","注销执业"],"answer":1,"explanation":"医师变更执业地点、类别、范围等应办理变更注册。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2621","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师在执业活动中应履行的义务不包括","options":["宣传健康知识","遵守法律法规","保护患者隐私","获取工资报酬"],"answer":3,"explanation":"获取报酬为医师权利，非义务。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2622","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师在执业活动中享有的权利不包括","options":["接受培训","获得报酬","遵守诊疗规范","提出意见建议"],"answer":2,"explanation":"遵守诊疗规范为义务，非权利。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2623","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师实施医疗、预防、保健措施，签署有关医学证明文件，必须","options":["随意签署","凭经验签署","由他人代签","亲自诊查、调查"],"answer":3,"explanation":"医师签署医学证明文件须亲自诊查、调查，不得伪造、篡改。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2624","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师不得出具与自己执业范围无关或者与执业类别不相符的医学证明文件，这一规定属于","options":["执业保障","执业权利","执业义务","执业规则"],"answer":3,"explanation":"此为医师执业规则中的禁止性规定。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2625","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"未经医师亲自诊查，医疗机构不得出具","options":["收费单","疾病诊断书、健康证明书等医学证明文件","处方","病历"],"answer":1,"explanation":"未经亲自诊查不得出具疾病诊断书、健康证明书、死亡证明书等。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2626","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师发现传染病疫情时，应当按照规定","options":["及时向所在机构报告","隐瞒不报","仅告知家属","自行处理"],"answer":0,"explanation":"医师发现疫情应按规定及时报告，不得隐瞒、缓报、谎报。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2627","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师对急危患者应当采取紧急措施进行诊治，","options":["不得拒绝急救处置","可拒绝","可延迟","可转诊后处理"],"answer":0,"explanation":"对急危患者，医师应采取紧急措施，不得拒绝急救处置。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2628","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"执业医师资格考试的条件不包括","options":["具有医学专业学历","在医疗机构试用期满一年","通过考试","年满18周岁"],"answer":0,"explanation":"报考条件包括学历、试用期等，18周岁非法定条件。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2629","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构执业必须进行","options":["工商登记","登记并取得《医疗机构执业许可证》","税务登记","无需许可"],"answer":1,"explanation":"医疗机构执业须登记取得执业许可证，按核准范围执业。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2630","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构不得因就诊者是传染病病人而","options":["上报疫情","正常治疗","隔离治疗","拒绝治疗或歧视"],"answer":3,"explanation":"医疗机构不得拒绝治疗或歧视传染病病人。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2631","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构施行手术、特殊检查或特殊治疗时，必须征得","options":["患者同意，并取得其家属或关系人签字（紧急情况除外）","仅医生同意","仅护士同意","无需同意"],"answer":0,"explanation":"手术、特殊治疗须征得患者同意并签字；不能签字时由家属或关系人同意并签字。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2632","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗事故的构成要件不包括","options":["患者主观不满意","医疗机构及其医务人员","违反医疗卫生法规","过失造成患者人身损害"],"answer":0,"explanation":"医疗事故构成要件包括主体、违法性、过失、人身损害及因果关系，患者主观不满意非要件。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2633","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗事故分为","options":["二级","三级","五级","四级"],"answer":3,"explanation":"医疗事故分四级：一级（死亡、重度残疾）、二级、三级、四级。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2634","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"造成患者死亡或重度残疾的医疗事故属于","options":["二级","一级医疗事故","三级","四级"],"answer":1,"explanation":"一级医疗事故指造成患者死亡、重度残疾。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2635","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"发生医疗事故争议时，病历资料应","options":["由医院单方保管","在医患双方在场情况下封存","由患者保管","销毁"],"answer":1,"explanation":"病历应医患双方在场封存，由医疗机构保管。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2636","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"患者有权复印的病历资料不包括","options":["住院志","门诊病历","主观病历（病例讨论记录）","检验报告"],"answer":2,"explanation":"患者可复印客观病历；主观病历（讨论记录等）不可复印但可封存。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2637","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗事故技术鉴定由","options":["法院组织","医学会组织","卫生行政部门直接鉴定","医院自行鉴定"],"answer":1,"explanation":"医疗事故技术鉴定由医学会组织专家鉴定组进行。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2638","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《医疗事故处理条例》规定，医疗事故赔偿争议的解决途径不包括","options":["刑事拘留","行政调解","民事诉讼","自行协商"],"answer":3,"explanation":"解决途径为协商、行政调解、民事诉讼，无刑事拘留。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2639","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《中华人民共和国传染病防治法》规定，传染病防治的方针是","options":["预防为主、防治结合、分类管理","治疗为主","隔离为主","消毒为主"],"answer":0,"explanation":"传染病防治实行预防为主、防治结合、分类管理的方针。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2640","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"传染病病人、病原携带者和疑似传染病病人，在治愈前或者在排除传染病嫌疑前，不得从事","options":["任何工作","法律禁止的易使该传染病扩散的工作","轻体力工作","居家活动"],"answer":1,"explanation":"不得从事法律禁止的易使传染病扩散的工作（如餐饮、托幼等）。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2641","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构发现甲类传染病时，应当及时采取的措施不包括","options":["对密切接触者医学观察","对病人予以隔离治疗","对疑似病人隔离治疗前指定场所隔离","对疑似病人进行居家隔离"],"answer":3,"explanation":"甲类传染病疑似病人应在指定场所单独隔离治疗，非居家隔离。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2642","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构对本单位内被传染病病原体污染的场所、物品以及医疗废物，应","options":["堆放","随意处理","出售","实施消毒处理"],"answer":3,"explanation":"应按规定消毒处理，医疗废物按《医疗废物管理条例》处置。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2643","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗废物分为","options":["三类","五类","四类","六类"],"answer":1,"explanation":"医疗废物分感染性、损伤性、病理性、药物性、化学性五类。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2644","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗废物暂时贮存的时间不得超过","options":["1天","2天","3天","7天"],"answer":1,"explanation":"医疗废物暂时贮存不超过2天，由有资质单位集中处置。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2645","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《中华人民共和国药品管理法》规定，药品生产必须","options":["税务登记","工商登记","取得药品生产许可证","无需许可"],"answer":2,"explanation":"药品生产须取得药品生产许可证，符合GMP要求。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2646","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"药品不良反应是指","options":["合格药品在正常用法用量下出现的与用药目的无关的有害反应","假药反应","过量反应","过敏反应"],"answer":0,"explanation":"药品不良反应定义强调合格药品、正常用法用量。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2647","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"药品不良反应报告的原则是","options":["确诊后报","可疑即报","严重后报","不报"],"answer":1,"explanation":"药品不良反应实行可疑即报原则。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2648","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"国家实行药品不良反应报告制度，医疗机构发现药品不良反应应","options":["按规定报告","隐瞒","仅告知患者","自行处理"],"answer":0,"explanation":"医疗机构应按规定及时报告药品不良反应。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2649","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"处方管理办法规定，处方应由","options":["护士开具","取得处方权的医师开具","药师开具","患者自行开具"],"answer":1,"explanation":"处方由取得处方权的执业医师开具，药师审核调配。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2650","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"处方一般不得超过","options":["30日用量","3日用量","15日用量","7日用量"],"answer":3,"explanation":"处方一般不超过7日用量，急诊处方不超过3日用量。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2651","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"麻醉药品和第一类精神药品处方不得超过","options":["7日用量","3日用量","1日用量","15日用量"],"answer":2,"explanation":"麻醉药品和第一类精神药品处方不超过1日用量（门诊）。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2652","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"第二类精神药品处方一般不得超过","options":["3日用量","1日用量","7日用量","15日用量"],"answer":2,"explanation":"第二类精神药品处方一般不超过7日用量。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2653","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构应当对麻醉药品处方进行","options":["销毁","随意处理","保存1年","专册登记，保存3年"],"answer":3,"explanation":"麻醉药品处方保存3年，精神药品处方保存2年，普通处方保存1年。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2654","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《中华人民共和国献血法》规定，国家提倡","options":["强制献血","十八周岁至五十五周岁的健康公民自愿献血","有偿献血","儿童献血"],"answer":1,"explanation":"献血法提倡18～55周岁健康公民自愿献血。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2655","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"血站采集血液必须","options":["仅登记","随意采集","不检查","进行健康检查"],"answer":3,"explanation":"血站对献血者必须免费进行必要的健康检查。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2656","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构临床用血应当","options":["随意用血","制定用血计划，合理用血","大量用血","不用血"],"answer":1,"explanation":"临床用血应合理、节约，推行成分输血。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2657","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《中华人民共和国母婴保健法》规定，婚前医学检查包括","options":["严重遗传性疾病、指定传染病、有关精神病","所有疾病","仅体检","仅化验"],"answer":0,"explanation":"婚前医学检查针对严重遗传病、指定传染病和有关精神病。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2658","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"母婴保健技术服务的内容不包括","options":["孕产期保健","婚前保健","器官移植","新生儿疾病筛查"],"answer":2,"explanation":"母婴保健技术服务包括婚前、孕产期、婴幼儿保健等，不含器官移植。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2659","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《医疗机构管理条例》规定，医疗机构必须将《医疗机构执业许可证》、诊疗科目、诊疗时间和收费标准","options":["不公示","保密","存档","悬挂于明显处"],"answer":3,"explanation":"医疗机构应将执业许可证等悬挂于明显处，接受监督。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2660","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构工作人员上岗时，必须","options":["佩戴载有本人姓名、职务或职称的标牌","不佩戴","随意着装","不挂牌"],"answer":0,"explanation":"工作人员应佩戴标牌，便于患者识别。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2661","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《中华人民共和国医务人员医德规范》的核心是","options":["个人利益","经济效益","救死扶伤，实行社会主义人道主义","单位利益"],"answer":2,"explanation":"医德规范核心为救死扶伤、防病治病，实行社会主义人道主义，全心全意为人民健康服务。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2662","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医德规范中，对医务人员的基本要求是","options":["尊重患者的人格与权利","服从领导","完成指标","维护单位"],"answer":0,"explanation":"医德规范要求尊重患者人格与权利，不分民族、性别、职业、地位，一视同仁。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2663","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学伦理学的基本原则是","options":["效益、效率","自主、保密","公平、公开","尊重、不伤害、有利、公正"],"answer":3,"explanation":"医学伦理四原则：尊重（自主）、不伤害、有利（行善）、公正。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2664","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学伦理学中，尊重原则的核心是","options":["尊重患者的人格和自主权","服从患者","患者至上","医生决定"],"answer":0,"explanation":"尊重原则要求尊重患者人格、自主决定权及隐私。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2665","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"知情同意的主体是","options":["家属","具有完全民事行为能力的患者本人","医生","单位"],"answer":1,"explanation":"知情同意由患者本人决定；无民事行为能力者由法定代理人代行。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2666","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"患者知情同意权的内容不包括","options":["决定治疗方案由医生全权负责","了解病情","了解治疗方案","了解医疗费用"],"answer":3,"explanation":"患者有权了解病情、方案、费用并自主选择，医生不能全权代替患者决定。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2667","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗保密的内容不包括","options":["为医院保密","为患者保密","向无关人员泄露患者隐私","为同事保密"],"answer":2,"explanation":"医疗保密要求不向无关人员泄露患者隐私及诊疗信息。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2668","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学伦理学中，公正原则是指","options":["公平、合理地分配卫生资源","平均分配","按需分配","按地位分配"],"answer":0,"explanation":"公正原则包括资源分配公正和人际交往公正。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2669","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学伦理学中，不伤害原则是指","options":["避免使患者受到不应有的伤害","不治疗","不手术","不检查"],"answer":0,"explanation":"不伤害原则要求避免可避免的伤害，权衡利弊。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2670","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学伦理学中，有利原则是指","options":["社会利益","医院利益","医生利益","把患者利益放在首位，促进其健康"],"answer":3,"explanation":"有利原则要求医务人员的行为对患者有利，促进健康。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2671","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"临床诊疗伦理原则不包括","options":["知情同意原则","整体化原则","最优化原则","利益最大化原则"],"answer":1,"explanation":"临床诊疗伦理原则包括整体化、最优化、知情同意、协同一致等，不含利益最大化。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2672","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"临床诊疗中的最优化原则是指","options":["最快方案","最贵方案","以最小代价获得最佳诊疗效果","最新方案"],"answer":2,"explanation":"最优化原则要求疗效最佳、安全、痛苦少、费用低。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2673","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"人体器官捐献应遵循的原则是","options":["强制","有偿","自愿、无偿","随意"],"answer":2,"explanation":"人体器官捐献遵循自愿、无偿原则，禁止买卖器官。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2674","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"人体器官移植应遵循的原则不包括","options":["伦理审查","买卖器官","知情同意","非商业"],"answer":1,"explanation":"器官移植须伦理审查、知情同意，禁止商业买卖。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2675","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"涉及人的生物医学研究应遵循的原则不包括","options":["以科学利益为重","知情同意","保护受试者","伦理审查"],"answer":0,"explanation":"研究应以受试者健康利益为重，非科学利益优先。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2676","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"伦理委员会的职责不包括","options":["审查研究方案","批准研究经费","保护受试者权益","监督研究过程"],"answer":1,"explanation":"伦理委员会审查研究方案、保护受试者，不负责经费审批。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2677","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学研究中的知情同意书应包括","options":["仅受益","仅研究目的","仅风险","研究目的、方法、风险、受益及自愿退出权利"],"answer":3,"explanation":"知情同意书应全面告知研究信息，保障受试者权益。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2678","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"患者自主选择权的含义是","options":["患者有权选择医疗机构、医生及诊疗方案","患者决定一切","医生决定","家属决定"],"answer":0,"explanation":"患者自主选择权包括选择医疗机构、医生、诊疗方案等。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2679","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"保护患者隐私权的措施不包括","options":["保密病历","遮挡诊疗环境","公开患者病情","限制无关人员"],"answer":2,"explanation":"保护隐私应遮挡环境、保密病历，不得公开病情。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2680","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学人文关怀的核心是","options":["以医院为中心","以疾病为中心","以医生为中心","以患者为中心，尊重生命"],"answer":3,"explanation":"医学人文关怀强调以患者为中心，尊重生命价值。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2681","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医患关系的模式中，最理想的是","options":["共同参与型","主动-被动型","指导-合作型","命令型"],"answer":0,"explanation":"医患关系三种模式中，共同参与型最理想，体现平等合作。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2682","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医患沟通的基本原则不包括","options":["单向告知","尊重","真诚","有效"],"answer":0,"explanation":"医患沟通应双向、尊重、真诚、有效，非单向告知。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2683","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医患沟通中，医生应","options":["打断患者","倾听患者诉求，耐心解释","敷衍","回避"],"answer":1,"explanation":"医患沟通应倾听、共情、耐心解释，建立信任。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2684","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗纠纷预防的措施不包括","options":["完善病历","规范诊疗","有效沟通","隐瞒病情"],"answer":3,"explanation":"预防医疗纠纷应规范诊疗、有效沟通、完善病历，不得隐瞒病情。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2685","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《医疗纠纷预防和处理条例》规定，发生医疗纠纷后，患者可选择的途径不包括","options":["协商","聚众闹事","人民调解","诉讼"],"answer":1,"explanation":"医疗纠纷解决途径为协商、人民调解、行政调解、诉讼，不得聚众闹事。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2686","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"病历书写的基本要求不包括","options":["规范","客观、真实、准确","及时、完整","主观臆造"],"answer":3,"explanation":"病历书写应客观、真实、准确、及时、完整、规范，不得臆造。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2687","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"病历书写中，抢救记录应在抢救结束后","options":["48小时内","24小时内","12小时内","6小时内据实补记"],"answer":3,"explanation":"抢救结束后6小时内据实补记抢救记录。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2688","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"手术记录应由","options":["护士书写","术者书写","家属书写","患者书写"],"answer":1,"explanation":"手术记录由术者在术后24小时内完成。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2689","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《中华人民共和国医师法》施行的时间是","options":["2022年3月1日","1999年5月1日","2020年1月1日","2021年1月1日"],"answer":0,"explanation":"《医师法》于2022年3月1日施行，取代原《执业医师法》。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2690","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"《医师法》规定，医师应当坚持","options":["经济效益为中心","人民健康为中心","个人发展为中心","单位利益为中心"],"answer":1,"explanation":"医师应坚持人民健康为中心，履行防病治病、救死扶伤的职责。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2691","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师应当遵循的临床诊疗指南是","options":["个人经验","国家发布的诊疗指南和临床路径","网络资料","民间偏方"],"answer":1,"explanation":"医师应遵循国家发布的诊疗指南、临床路径和技术操作规范。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2692","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师在诊疗活动中应当使用","options":["自制药","随意药品","过期药品","经依法批准并按规定开具的药品和医疗器械"],"answer":3,"explanation":"医师应使用经批准的药品和器械，按规定开具。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2693","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医师不得利用职务之便","options":["正常休息","正常收费","正常诊疗","索要、收受财物或不正当利益"],"answer":3,"explanation":"医师不得索要、收受患者财物或不正当利益。","exam":"医疗编","__sub":"卫生法规与伦理","diff":1,"id":"yl-2694","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"违反《医师法》规定，医师造成医疗事故的，应承担的法律责任不包括","options":["民事责任","行政责任","刑事责任","道德谴责"],"answer":2,"explanation":"法律责任包括行政、民事、刑事责任，道德谴责非法律责任。","exam":"医疗编","__sub":"卫生法规与伦理","diff":2,"id":"yl-2695","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学心理学的研究对象是","options":["心理因素与健康和疾病的相互关系","仅疾病","仅药物","仅手术"],"answer":0,"explanation":"医学心理学研究心理社会因素在健康与疾病中的作用及相互关系。","exam":"医疗编","__sub":"医学心理与人文","diff":1,"id":"yl-2696","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学模式的发展经历了","options":["神灵主义、自然哲学、机械论、生物医学、生物-心理-社会医学模式","仅生物医学模式","仅心理模式","无变化"],"answer":0,"explanation":"医学模式从神灵主义到生物-心理-社会医学模式不断演进。","exam":"医疗编","__sub":"医学心理与人文","diff":1,"id":"yl-2697","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"现代医学模式是","options":["生物医学模式","生物-心理-社会医学模式","自然哲学模式","机械论模式"],"answer":1,"explanation":"1977年恩格尔提出生物-心理-社会医学模式。","exam":"医疗编","__sub":"医学心理与人文","diff":1,"id":"yl-2698","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"心理评估的常用方法不包括","options":["体格检查","观察法","会谈法","心理测验法"],"answer":0,"explanation":"心理评估常用观察、会谈、心理测验等，体格检查非心理评估方法。","exam":"医疗编","__sub":"医学心理与人文","diff":2,"id":"yl-2699","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"心理测验按功能分类不包括","options":["智力测验","人格测验","神经心理测验","血常规检查"],"answer":0,"explanation":"心理测验按功能分智力、人格、神经心理等测验，血常规非心理测验。","exam":"医疗编","__sub":"医学心理与人文","diff":2,"id":"yl-2700","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"常用的智力测验量表是","options":["明尼苏达多相人格调查表","艾森克人格问卷","SCL-90","韦氏智力量表"],"answer":3,"explanation":"韦氏智力量表（WAIS）为常用智力测验；艾森克、明尼苏达为人格测验。","exam":"医疗编","__sub":"医学心理与人文","diff":1,"id":"yl-2701","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"常用的自评症状量表是","options":["SCL-90（症状自评量表）","韦氏量表","比奈量表","瑞文测验"],"answer":0,"explanation":"SCL-90为常用精神症状自评量表。","exam":"医疗编","__sub":"医学心理与人文","diff":1,"id":"yl-2702","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"心理治疗的主要方法不包括","options":["精神分析","药物治疗","行为治疗","认知治疗"],"answer":1,"explanation":"心理治疗包括精神分析、行为、认知、人本主义等，药物治疗非心理治疗。","exam":"医疗编","__sub":"医学心理与人文","diff":2,"id":"yl-2703","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"行为治疗的理论基础是","options":["精神分析理论","条件反射理论","人本主义理论","认知理论"],"answer":1,"explanation":"行为治疗以经典条件反射和操作性条件反射为理论基础。","exam":"医疗编","__sub":"医学心理与人文","diff":1,"id":"yl-2704","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"系统脱敏疗法适用于","options":["精神分裂症","恐惧症","器质性疾病","昏迷"],"answer":1,"explanation":"系统脱敏用于恐惧、焦虑等，通过逐步暴露减轻反应。","exam":"医疗编","__sub":"医学心理与人文","diff":1,"id":"yl-2705","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"认知治疗的核心是","options":["改变不合理认知","改变行为","改变环境","改变药物"],"answer":0,"explanation":"认知治疗通过识别和改变不合理认知改善情绪和行为。","exam":"医疗编","__sub":"医学心理与人文","diff":1,"id":"yl-2706","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"患者角色的适应不良类型不包括","options":["角色行为缺如","角色行为增强","角色行为冲突","角色行为消退"],"answer":1,"explanation":"患者角色适应不良包括缺如、冲突、减退、强化、异常等，无“增强”类型。","exam":"医疗编","__sub":"医学心理与人文","diff":2,"id":"yl-2707","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"患者角色行为强化是指","options":["拒绝承认患病","安于患者角色，不愿恢复","隐瞒病情","积极配合"],"answer":1,"explanation":"角色强化指患者安于角色、依赖性增强，不愿恢复社会角色。","exam":"医疗编","__sub":"医学心理与人文","diff":1,"id":"yl-2708","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医患关系的基本模式不包括","options":["主动-被动型","指导-合作型","共同参与型","对立-冲突型"],"answer":0,"explanation":"医患关系三种模式：主动-被动、指导-合作、共同参与，无对立-冲突型。","exam":"医疗编","__sub":"医学心理与人文","diff":2,"id":"yl-2709","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"共同参与型医患关系适用于","options":["休克患者","昏迷患者","婴幼儿","慢性病且有一定文化水平的患者"],"answer":3,"explanation":"共同参与型适用于慢性病、有自主能力的患者。","exam":"医疗编","__sub":"医学心理与人文","diff":1,"id":"yl-2710","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医患沟通中，非语言沟通不包括","options":["姿势","表情","书面通知","眼神"],"answer":2,"explanation":"非语言沟通包括表情、姿势、眼神、触摸等，书面通知为语言沟通。","exam":"医疗编","__sub":"医学心理与人文","diff":2,"id":"yl-2711","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医务人员的心理素质要求不包括","options":["耐心","情绪稳定","情绪不稳定","同理心"],"answer":2,"explanation":"医务人员应情绪稳定、耐心、有同理心，情绪不稳定为不良素质。","exam":"医疗编","__sub":"医学心理与人文","diff":2,"id":"yl-2712","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"共情是指","options":["说教","同情","怜悯","设身处地理解患者感受"],"answer":3,"explanation":"共情（同理心）指设身处地理解并回应患者感受。","exam":"医疗编","__sub":"医学心理与人文","diff":1,"id":"yl-2713","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"临终关怀的理念是","options":["加速死亡","延长生命","提高临终患者生命质量，减轻痛苦","放弃治疗"],"answer":2,"explanation":"临终关怀以提高生命质量、减轻痛苦、维护尊严为目标。","exam":"医疗编","__sub":"医学心理与人文","diff":1,"id":"yl-2714","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医学人文精神的核心是","options":["技术至上","追求经济效益","尊重人的生命价值","效率优先"],"answer":2,"explanation":"医学人文精神强调尊重生命、以人为本。","exam":"医疗编","__sub":"医学心理与人文","diff":1,"id":"yl-2715","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"利巴韦林属于？","options":["抗真菌药","抗细菌药","广谱抗病毒药","抗结核药"],"answer":2,"explanation":"利巴韦林（病毒唑）为广谱抗病毒药，对RNA病毒作用较强。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-2716","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"齐多夫定属于？","options":["抗疱疹病毒药","核苷类逆转录酶抑制剂（抗HIV药）","抗流感病毒药","抗真菌药"],"answer":1,"explanation":"齐多夫定为首个抗HIV药物，抑制逆转录酶，用于艾滋病治疗。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2717","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"氟康唑属于？","options":["抗真菌药","抗病毒药","抗细菌药","抗寄生虫药"],"answer":0,"explanation":"氟康唑为三唑类抗真菌药，对念珠菌、隐球菌有效，可透过血脑屏障。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-2718","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"两性霉素B的主要不良反应是？","options":["出血性膀胱炎","耳毒性","周围神经炎","肾毒性和发热寒战"],"answer":3,"explanation":"两性霉素B为深部真菌感染首选，但肾毒性明显，静滴常有寒战高热。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-2719","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"甲硝唑抗厌氧菌的机制是？","options":["抑制叶酸合成","抑制细胞壁合成","抑制蛋白质合成","其代谢产物使厌氧菌DNA断裂"],"answer":3,"explanation":"甲硝唑在厌氧菌体内被还原，生成使DNA断裂的产物而杀菌。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-2720","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"喹碘方主要用于？","options":["血吸虫病","肠外阿米巴肝脓肿","疟疾","肠内阿米巴病"],"answer":3,"explanation":"喹碘方等卤化喹啉类作用于肠腔内阿米巴，用于肠内阿米巴病。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-2721","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"乙胺嗪用于治疗？","options":["蛔虫病","血吸虫病","疟疾","丝虫病"],"answer":3,"explanation":"乙胺嗪（海群生）为抗丝虫病首选药。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2722","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"吡喹酮的主要用途是？","options":["阿米巴病","丝虫病","疟疾","血吸虫病和绦虫病"],"answer":3,"explanation":"吡喹酮为广谱抗吸虫、抗绦虫药，是血吸虫病首选。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2723","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"青蒿素的主要作用是？","options":["杀灭配子体","根治间日疟","预防疟疾","杀灭红内期疟原虫，用于耐氯喹疟疾"],"answer":3,"explanation":"青蒿素杀灭红内期裂殖体，作用快，用于耐氯喹恶性疟和脑型疟抢救。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2724","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"左旋咪唑属于？","options":["单纯驱虫药","驱肠虫兼免疫调节药","抗生素","抗病毒药"],"answer":1,"explanation":"左旋咪唑驱蛔虫等，兼有增强免疫功能的作用。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2725","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"氯解磷定用于？","options":["有机磷中毒（恢复胆碱酯酶活性）","氰化物中毒","一氧化碳中毒","酒精中毒"],"answer":0,"explanation":"氯解磷定使被抑制的胆碱酯酶恢复活性，与阿托品合用治疗有机磷中毒。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2726","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"氰化物中毒的解救药组合是？","options":["阿托品+氯解磷定","亚硝酸钠+硫代硫酸钠","纳洛酮+维生素C","美蓝+阿托品"],"answer":1,"explanation":"亚硝酸钠形成高铁血红蛋白结合氰离子，硫代硫酸钠使氰离子转为无毒硫氰酸盐排出。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-2727","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"亚硝酸盐中毒的解救药是？","options":["阿托品","硫代硫酸钠","亚甲蓝（美蓝）","纳洛酮"],"answer":2,"explanation":"小剂量亚甲蓝使高铁血红蛋白还原为血红蛋白，用于亚硝酸盐中毒。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2728","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"一氧化碳中毒的首要处理是？","options":["注射呼吸兴奋剂","迅速脱离中毒环境，给予氧气","应用亚甲蓝","洗胃"],"answer":1,"explanation":"CO中毒立即脱离环境、吸氧（高压氧疗效最佳），促进碳氧血红蛋白解离。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-2729","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"美蓝（亚甲蓝）用于下列哪种中毒？","options":["有机磷中毒","亚硝酸盐中毒（小剂量）","氰化物中毒单用","酒精中毒"],"answer":1,"explanation":"小剂量美蓝还原高铁血红蛋白，用于亚硝酸盐等所致高铁血红蛋白血症。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2730","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"酒精（乙醇）急性中毒昏迷期的解救可用？","options":["氯解磷定","阿托品","美蓝","纳洛酮"],"answer":3,"explanation":"纳洛酮可拮抗乙醇中毒所致内啡肽效应，用于急性酒精中毒昏迷的救治。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2731","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"氟乙酰胺中毒的特效解救药是？","options":["纳洛酮","乙酰胺（解氟灵）","美蓝","阿托品"],"answer":1,"explanation":"乙酰胺与氟乙酰胺竞争酰胺酶，是灭鼠药氟乙酰胺中毒的特效解毒药。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-2732","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"重金属铅中毒的首选解毒药是？","options":["纳洛酮","美蓝","依地酸钙钠（EDTA）","阿托品"],"answer":2,"explanation":"依地酸钙钠与多种金属离子络合促排出，用于铅中毒。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2733","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"汞中毒的首选解毒药是？","options":["依地酸钙钠","二巯基丙磺酸钠","美蓝","亚硝酸钠"],"answer":1,"explanation":"二巯基类药物与汞离子结合促排出，用于汞、砷中毒。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2734","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"铁剂中毒（儿童误服）的解毒药是？","options":["美蓝","去铁胺","纳洛酮","乙酰胺"],"answer":1,"explanation":"去铁胺与铁离子特异性络合，用于急性铁剂中毒。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-2735","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"药物依赖性可分为？","options":["急性和慢性","身体依赖性和精神依赖性","主动和被动","先天和后天"],"answer":1,"explanation":"身体依赖性表现为停药后戒断症状；精神依赖性表现为强烈心理渴求。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-2736","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"麻醉药品的管理原则是？","options":["患者自购自用","按普通药品管理","专人负责、专柜加锁、专用账册、专用处方、专册登记","可随意处方"],"answer":2,"explanation":"麻醉药品和精神药品实行五专管理，处方按规定保存备查。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-2737","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"处方中麻醉药品注射剂一般不得超过？","options":["15日用量","7日用量","1日用量","3日用量"],"answer":3,"explanation":"按规定，麻醉药品注射剂处方一般不超过3日用量，控缓释制剂不超过7日，其他剂型不超过7日（癌痛慢性疼痛按规定可延长）。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-2738","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"癌症疼痛三阶梯治疗中，重度疼痛选用？","options":["强阿片类（吗啡等）","非甾体抗炎药","弱阿片类（可待因）","抗抑郁药"],"answer":0,"explanation":"三阶梯：轻度用非甾体抗炎药，中度用弱阿片类，重度用强阿片类。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2739","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"药物临床试验的最基本原则是？","options":["降低试验成本","科学数据优先","加快试验进度","受试者权益、安全和健康高于科学利益"],"answer":3,"explanation":"药物临床试验质量管理规范（GCP）规定受试者权益保障优先于科学和社会利益。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2740","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"影响药物效应的机体因素不包括？","options":["年龄和体重","药物的剂型颜色","性别","病理状态"],"answer":1,"explanation":"剂型颜色不属于影响药效的机体因素（属药物方面因素且颜色无药理意义）。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2741","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"老年人用药剂量一般应？","options":["与成人相同","适当减少（约为成人量的3/4）","适当增加","加倍"],"answer":1,"explanation":"老年人肝肾功能减退，药物消除减慢，一般用量为成人的3/4左右。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2742","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿用药剂量的计算依据最常用的是？","options":["身高","体重（mg/kg）","年龄直接套用成人量","体表面积仅用于新生儿"],"answer":1,"explanation":"小儿剂量最常按体重计算（mg/kg），部分药物按体表面积计算更精确。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2743","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"妊娠期用药的原则是？","options":["随意用药","一律不用药","权衡利弊，尽量避免使用对胎儿有害的药物","只可用中药"],"answer":2,"explanation":"妊娠期用药须权衡母儿利弊，选用安全药物，孕早期尤其谨慎。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2744","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"哺乳期用药的原则是？","options":["必须断奶才能用药","随意用药","选择乳汁中分泌少、对婴儿无害的药物","只可用抗生素"],"answer":2,"explanation":"哺乳期选药应考虑乳汁药物浓度与婴儿影响，必要时暂停哺乳。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2745","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肝功能不全患者用药原则是？","options":["随意用药","加大剂量","避免或减量使用经肝代谢且有肝毒性的药物","只可用静脉药"],"answer":2,"explanation":"肝功能不全者药物代谢减慢，应避免肝毒性药物并适当减量。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2746","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肾功能不全患者用药原则是？","options":["减量或延长给药间隔（按肌酐清除率调整）","维持原量","加大剂量","只可用口服药"],"answer":0,"explanation":"肾功能不全者药物排泄减慢，需按肌酐清除率调整剂量或间隔。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2747","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"药物滥用是指？","options":["药物过敏","按医嘱用药","药物过量一次","不合理使用药物（尤其精神活性药物）导致依赖和危害"],"answer":3,"explanation":"药物滥用指背离医疗目的、反复大量使用具有依赖性特性的药物。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2748","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"耐药性（抗药性）是指？","options":["病原体或肿瘤细胞对药物的敏感性降低","机体对药物反应性降低","药物代谢加快","药物排泄加快"],"answer":0,"explanation":"耐药性是病原微生物或肿瘤细胞反复接触药物后产生的敏感性降低现象。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-2749","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"安慰剂效应属于？","options":["药物的真实药理作用","心理效应对药物效应的影响","药物的不良反应","药物的毒性反应"],"answer":1,"explanation":"安慰剂无药理活性，其效应源于患者的心理暗示和期望。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2750","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"安慰剂对照试验的主要目的是？","options":["排除心理因素和疾病自发变化的影响","减少样本量","缩短试验时间","降低成本"],"answer":0,"explanation":"随机双盲安慰剂对照可排除安慰剂效应和偏倚，是评价药效的金标准设计。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2751","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"双盲试验是指？","options":["双方均知道分组","仅受试者不知道分组","仅研究者不知道分组","研究者和受试者均不知道用药分组"],"answer":3,"explanation":"双盲设计中研究者和受试者都不知道分组情况，可减少主观偏倚。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2752","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"药物的不良反应包括？","options":["仅毒性反应","副作用、毒性反应、过敏反应、继发反应等","仅过敏反应","仅副作用"],"answer":1,"explanation":"不良反应包括副作用、毒性反应、变态反应、后遗效应、继发反应、特异质反应、致畸致癌等。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-2753","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"后遗效应是指？","options":["停药后血药浓度已降至阈浓度以下仍残留的效应","用药期间的副作用","过敏反应","药物蓄积中毒"],"answer":0,"explanation":"后遗效应指停药后残留的药理效应，如苯巴比妥次日晨的宿醉现象。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2754","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"特异质反应的特点是？","options":["仅过敏体质者发生","与剂量无关且人人发生","与遗传缺陷有关，少数特异体质者发生","与免疫有关"],"answer":2,"explanation":"特异质反应由遗传性酶缺陷等引起，如G6PD缺乏者用伯氨喹发生溶血。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-2755","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"药物协同作用与拮抗作用的本质区别是？","options":["合用后效应增强为协同、减弱为拮抗","剂量不同","给药途径不同","药物价格不同"],"answer":0,"explanation":"两药合用效应增强为协同（相加或增强），效应减弱为拮抗。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-2756","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"配伍禁忌是指？","options":["药物包装相似","药物价格不匹配","给药时间冲突","药物混合后发生理化性质或药理作用的改变"],"answer":3,"explanation":"配伍禁忌指药物配伍后发生浑浊、沉淀、失效或毒性增强等变化。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-2757","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"青霉素与下列哪种药物属配伍禁忌（不宜同瓶静滴）？","options":["氯化钠","庆大霉素","葡萄糖","维生素C"],"answer":1,"explanation":"β-内酰胺类与氨基糖苷类混合可相互灭活，属配伍禁忌，需分开给药。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-2758","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"影响药物效应的给药时间因素，例如？","options":["患者性别","药物颜色","药物价格","餐前餐后影响药物吸收"],"answer":3,"explanation":"食物影响药物吸收：铁剂餐后服减刺激，某些药需餐前服促吸收。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-2759","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"联合用药的目的不包括？","options":["增强疗效","增加药物不良反应","减少不良反应","延缓耐药性"],"answer":1,"explanation":"联合用药目的是增效、减毒、延缓耐药，而非增加不良反应。","exam":"医疗编","__sub":"药理学","diff":1,"id":"yl-2760","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"药物警戒的主要目的是？","options":["替代临床试验","推销药物","增加药物销量","发现、评价、理解和预防药物不良反应及其他相关问题"],"answer":3,"explanation":"药物警戒贯穿药品全生命周期，保障公众用药安全。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2761","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"药品不良反应报告的范围包括？","options":["可疑不良反应均需报告","新药上市后所有不良反应","仅严重不良反应","仅死亡病例"],"answer":1,"explanation":"药品不良反应监测实行可疑即报原则，可疑不良反应均应报告，及时收集信号。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2762","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"特殊药品管理中，精神药品分为？","options":["第一类和第二类精神药品","甲类和乙类","普通和特殊","一级和三级"],"answer":0,"explanation":"精神药品分第一类（依赖性强，如司可巴比妥）和第二类精神药品管理。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2763","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗机构麻醉药品处方保存期限为？","options":["3年","1年","5年","10年"],"answer":0,"explanation":"麻醉药品和第一类精神药品处方保存3年备查。","exam":"医疗编","__sub":"药理学","diff":2,"id":"yl-2764","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"医疗用毒性药品每次处方剂量不得超过？","options":["2日极量","3日用量","7日用量","1日极量"],"answer":0,"explanation":"毒性药品每次处方不得超过2日极量。","exam":"医疗编","__sub":"药理学","diff":3,"id":"yl-2765","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"原发性免疫缺陷病的发病原因是？","options":["HIV感染","遗传因素（先天）","营养不良","肿瘤"],"answer":1,"explanation":"原发性免疫缺陷为遗传或发育缺陷所致，继发性者由感染（HIV）、营养、药物等引起。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2766","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"凝集反应与沉淀反应的区别是？","options":["凝集反应的抗原为颗粒性抗原","凝集反应用可溶性抗原","沉淀反应抗原为颗粒性","无区别"],"answer":0,"explanation":"颗粒性抗原（细菌、红细胞）与抗体结合出现凝集；可溶性抗原与抗体形成沉淀。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2767","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"ELISA（酶联免疫吸附试验）的原理是？","options":["凝集反应","补体结合","抗原抗体反应+酶标记显色","中和反应"],"answer":2,"explanation":"ELISA用酶标记抗体，抗原抗体结合后加底物显色，灵敏度高，广泛用于检测抗原或抗体。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2768","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肥达反应用于诊断？","options":["梅毒","风湿热","结核病","伤寒和副伤寒"],"answer":3,"explanation":"肥达反应检测伤寒沙门菌O、H抗原的抗体，辅助诊断伤寒。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2769","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"梅毒的血清学筛查试验常用？","options":["PPD试验","肥达反应","ASO试验","RPR/USR（非特异性）"],"answer":3,"explanation":"梅毒筛查用RPR等非特异性试验，阳性者用TPPA等特异性试验确认。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2770","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"血型抗原的本质是？","options":["白细胞抗原","血浆蛋白","红细胞表面的糖蛋白/糖脂抗原","血小板抗原"],"answer":2,"explanation":"ABO血型抗原为红细胞膜上的糖蛋白/糖脂，由基因决定。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2771","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"Rh血型不合新生儿溶血多见于？","options":["Rh阴性母亲怀Rh阳性胎儿","Rh阳性母亲怀Rh阴性胎儿","AB型母亲","O型父亲"],"answer":0,"explanation":"Rh阴性母亲再次怀Rh阳性胎儿时，母体已产生抗D抗体，经胎盘破坏胎儿红细胞。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2772","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"O型血的红细胞表面？","options":["有A和B抗原","无A、B抗原，血浆中有抗A和抗B抗体","有D抗原","无任何抗体"],"answer":1,"explanation":"O型红细胞无A、B抗原，血浆含天然抗A、抗B抗体，故称万能供血者（实际仍需同型输血）。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2773","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"AB型血的血浆中？","options":["无天然抗A、抗B抗体","有抗A抗体","有抗B抗体","有抗A和抗B抗体"],"answer":0,"explanation":"AB型红细胞有A、B抗原，血浆中无相应天然抗体。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2774","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"输血前必须进行的试验是？","options":["血常规","仅血型鉴定","仅肝功能检查","血型鉴定和交叉配血"],"answer":3,"explanation":"输血前必须做ABO和Rh血型鉴定及交叉配血试验，防止溶血性输血反应。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-2775","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"交叉配血试验的主侧是？","options":["供者红细胞+受者血浆","受者红细胞+供者血浆","供者血浆+供者红细胞","受者血浆+受者红细胞"],"answer":0,"explanation":"主侧为供者红细胞与受者血浆反应，检测受者血浆中抗体；次侧相反。","exam":"医疗编","__sub":"微生物与免疫","diff":3,"id":"yl-2776","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"免疫印迹（Western blot）用于？","options":["细菌培养","DNA测序","蛋白质（抗体）的确认检测","细胞计数"],"answer":2,"explanation":"免疫印迹检测特定蛋白质（如HIV确认试验检测抗体条带）。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2777","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"流式细胞术的主要用途是？","options":["病毒培养","细菌鉴定","检测细胞表面分子和细胞计数（如CD4+T细胞）","血药浓度"],"answer":2,"explanation":"流式细胞术用荧光标记抗体检测细胞表面标志，用于免疫分型和CD4计数。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2778","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"PCR技术用于？","options":["病原体核酸扩增检测","蛋白质检测","细胞形态观察","细菌染色"],"answer":0,"explanation":"聚合酶链反应（PCR）体外扩增核酸，用于病原体核酸检测（如HBV DNA定量）。","exam":"医疗编","__sub":"微生物与免疫","diff":1,"id":"yl-2779","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"类风湿因子的本质是？","options":["抗双链DNA抗体","抗核抗体","针对IgG Fc段的自身抗体（多为IgM）","补体"],"answer":2,"explanation":"类风湿因子（RF）是针对变性IgG Fc段的自身抗体，见于类风湿关节炎等。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2780","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"抗核抗体（ANA）升高最常见于？","options":["类风湿关节炎","系统性红斑狼疮","痛风","糖尿病"],"answer":1,"explanation":"ANA是系统性红斑狼疮的筛查指标，SLE患者阳性率高。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2781","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"系统性红斑狼疮的特征性抗体是？","options":["抗-HBs","类风湿因子","抗O抗体","抗双链DNA抗体和抗Sm抗体"],"answer":3,"explanation":"抗dsDNA和抗Sm抗体为SLE的标志性抗体，与病情活动相关。","exam":"医疗编","__sub":"微生物与免疫","diff":3,"id":"yl-2782","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"过敏原检测的体内试验是？","options":["流式细胞术","ELISA","免疫印迹","皮肤点刺试验"],"answer":3,"explanation":"皮肤点刺（皮内）试验为体内过敏原检测，操作简便、快速。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2783","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"免疫球蛋白的基本结构是？","options":["四条轻链","两条重链","由两条重链和两条轻链经二硫键连接","单条多肽链"],"answer":2,"explanation":"Ig单体由2条重链、2条轻链经二硫键连接成Y形结构。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2784","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"抗体与抗原结合的部位是？","options":["可变区（V区）","恒定区（C区）","铰链区","Fc段"],"answer":0,"explanation":"V区（尤其超变区/CDR）识别并结合抗原表位；C区（Fc段）介导效应功能。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2785","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"免疫球蛋白Fc段的功能是？","options":["结合抗原表位","与细胞Fc受体结合、激活补体","决定抗体特异性","运输氧"],"answer":1,"explanation":"Fc段介导调理、ADCC、激活补体等效应功能；V区结合抗原。","exam":"医疗编","__sub":"微生物与免疫","diff":3,"id":"yl-2786","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"单克隆抗体的特点是？","options":["由多个克隆产生","由单一克隆产生，特异性强、纯度高","特异性差","不能用于诊断"],"answer":1,"explanation":"单克隆抗体由单一B细胞克隆的杂交瘤产生，特异性强，广泛用于诊断和治疗。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2787","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"免疫佐剂的作用是？","options":["中和抗体","减弱免疫应答","直接杀灭病原体","增强抗原的免疫原性"],"answer":3,"explanation":"佐剂（如氢氧化铝）与抗原合用可增强免疫应答，用于疫苗制备。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2788","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"减毒活疫苗的优点是？","options":["不需要冷链","绝对安全","可大量生产无风险","免疫效果好、接种次数少（多为一次）"],"answer":3,"explanation":"减毒活疫苗模拟自然感染，免疫持久，但免疫缺陷者和孕妇慎用，需冷链保存。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2789","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"灭活疫苗的特点是？","options":["一次接种终身免疫","免疫效果持久","安全、需多次接种、免疫维持时间较短","不产生体液免疫"],"answer":2,"explanation":"灭活疫苗不能增殖，需多次加强，主要诱导体液免疫。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2790","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"类毒素的制备方法是？","options":["内毒素处理","外毒素经甲醛处理脱毒保留免疫原性","加热灭活","紫外线照射"],"answer":1,"explanation":"类毒素由外毒素经甲醛脱毒制成（如破伤风类毒素），保留抗原性、失去毒性。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2791","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"抗毒素血清的特点是？","options":["含抗生素","含抗原","含特异性抗体，可中和毒素，可能引起过敏","含疫苗"],"answer":2,"explanation":"抗毒素（如TAT）为免疫动物血清制剂，含特异性抗体，异种蛋白可致过敏。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2792","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"免疫荧光技术的用途是？","options":["血药浓度","细菌计数","抗原或抗体的定位检测","基因测序"],"answer":2,"explanation":"免疫荧光用荧光素标记抗体，检测组织或细胞中抗原的分布（如肾活检免疫荧光）。","exam":"医疗编","__sub":"微生物与免疫","diff":2,"id":"yl-2793","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"脑死亡的临床判断标准不包括？","options":["脑干反射全部消失","深昏迷","自主呼吸恢复","自主呼吸停止（需呼吸机维持）"],"answer":2,"explanation":"脑死亡标准：深昏迷、脑干反射消失、自主呼吸停止（呼吸激发试验阴性）、脑电图平坦等；自主呼吸恢复与脑死亡相反。","exam":"医疗编","__sub":"诊断学基础","diff":2,"id":"yl-2794","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肺性脑病的主要表现是？","options":["胸痛","单纯咳嗽加重","咯血","神志改变（嗜睡、烦躁、昏迷）"],"answer":3,"explanation":"肺性脑病由缺氧和CO₂潴留引起，表现为神志精神改变，是肺心病死亡主要原因。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2795","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"呼吸衰竭最常见的病因是？","options":["肺水肿","肺炎","气胸","慢性阻塞性肺疾病"],"answer":3,"explanation":"COPD是呼吸衰竭最常见病因（通气与换气功能障碍）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2796","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"呼吸衰竭患者氧疗的原则（Ⅱ型）是？","options":["低浓度持续吸氧（25-33%）","高浓度吸氧","间断吸氧","不需吸氧"],"answer":0,"explanation":"Ⅱ型呼衰靠低氧刺激呼吸中枢，高浓度氧抑制呼吸致CO₂潴留加重，用低浓度持续氧疗。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2797","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"支气管肺癌的早期表现是？","options":["高热寒战","大量脓痰","刺激性干咳、痰中带血","下肢水肿"],"answer":2,"explanation":"肺癌早期表现为刺激性干咳、痰中带血（40岁以上吸烟者警惕）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2798","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"霍乱的治疗关键是？","options":["抗生素","补液（纠正脱水）","止泻","禁食"],"answer":1,"explanation":"霍乱治疗关键是迅速补液纠正脱水（口服补液盐或静脉补液），抗生素为辅助。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2799","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"伤寒的典型表现不包括？","options":["玫瑰疹","持续高热","相对缓脉","脉搏增快与体温不成比例（相对缓脉相反）"],"answer":3,"explanation":"伤寒典型表现：持续高热、相对缓脉（脉搏不随体温升高而增快）、玫瑰疹、肝脾大、白细胞减少。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2800","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"细菌性痢疾的确诊依据是？","options":["粪便培养出志贺菌","症状典型","血常规","乙状结肠镜"],"answer":0,"explanation":"粪便培养出志贺菌是菌痢确诊依据。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2801","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"流行性脑脊髓膜炎的病原体是？","options":["结核杆菌","脑膜炎奈瑟菌","新型隐球菌","流感嗜血杆菌"],"answer":1,"explanation":"流脑由脑膜炎奈瑟菌引起，冬春季流行，皮肤瘀点瘀斑为特征。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2802","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"流行性乙型脑炎的主要表现是？","options":["高热、意识障碍、抽搐、呼吸衰竭","皮疹","腹泻","关节痛"],"answer":0,"explanation":"乙脑：高热、意识障碍、抽搐、呼吸衰竭（呼吸衰竭为主要死因）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2803","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"疟疾的典型发作表现是？","options":["寒战、高热、大汗，间歇期无症状","持续低热","皮疹","腹泻"],"answer":0,"explanation":"疟疾典型发作分三期：寒战期、高热期、大汗期，间歇期无症状（间日疟隔日发作）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2804","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"血吸虫病的主要传播途径是？","options":["接触疫水（尾蚴经皮肤侵入）","飞沫","食物","血液"],"answer":0,"explanation":"血吸虫尾蚴经皮肤侵入，疫水接触是主要传播途径。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2805","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"艾滋病患者最常见的死亡原因是？","options":["出血","机会性感染和恶性肿瘤","心衰","肾衰"],"answer":1,"explanation":"AIDS患者因免疫功能缺陷，死于机会性感染（如肺孢子菌肺炎）和肿瘤（卡波西肉瘤等）。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2806","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肺孢子菌肺炎是下列哪种疾病最常见的并发症？","options":["艾滋病","糖尿病","肝硬化","慢性肾炎"],"answer":0,"explanation":"肺孢子菌肺炎（PCP）是艾滋病患者最常见的机会性感染，表现为进行性呼吸困难。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2807","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"梅毒的首选治疗药物是？","options":["红霉素","青霉素","四环素","庆大霉素"],"answer":1,"explanation":"梅毒首选苄星青霉素肌注，对青霉素过敏者用多西环素。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2808","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"淋病的病原体是？","options":["淋病奈瑟菌（革兰阴性双球菌）","梅毒螺旋体","衣原体","支原体"],"answer":0,"explanation":"淋病由淋病奈瑟菌引起，表现为尿道炎（脓性分泌物）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2809","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"尖锐湿疣的病原体是？","options":["人乳头瘤病毒（HPV）","单纯疱疹病毒","巨细胞病毒","EB病毒"],"answer":0,"explanation":"尖锐湿疣由HPV（6、11型等）引起，表现为外生殖器菜花状赘生物。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2810","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"生殖器疱疹的病原体是？","options":["HBV","HPV","HIV","单纯疱疹病毒（HSV-2为主）"],"answer":3,"explanation":"生殖器疱疹由HSV-2引起，反复发作的簇集性水疱。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2811","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"结核性腹膜炎的腹水特点是？","options":["渗出液、ADA升高、淋巴细胞为主","漏出液","血性为主（必然）","中性粒细胞为主"],"answer":0,"explanation":"结核性腹膜炎腹水为渗出液，淋巴细胞为主、ADA升高、蛋白高。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2812","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"上消化道大出血的首要处理是？","options":["手术","急诊胃镜","口服止血药","补充血容量（快速输液输血）"],"answer":3,"explanation":"上消化道大出血：立即建立静脉通道补充血容量（先晶体后胶体，输血指征明确），再病因治疗。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2813","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"上消化道大出血停止的指标不包括？","options":["肠鸣音正常","血压稳定、脉搏正常","血红蛋白持续下降","尿素氮下降"],"answer":2,"explanation":"出血停止指标：血压脉搏稳定、肠鸣音正常、尿素氮下降、黑便停止；血红蛋白持续下降提示继续出血。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2814","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"消化性溃疡出血的药物治疗首选？","options":["铋剂","H2受体拮抗剂","硫糖铝","质子泵抑制剂（静脉）"],"answer":3,"explanation":"PPI强烈抑酸提高胃内pH，促进血小板聚集和凝血，是溃疡出血首选。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2815","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肝硬化腹水的治疗不包括？","options":["利尿剂（螺内酯+呋塞米）","限钠","大量放腹水不加白蛋白","补充白蛋白"],"answer":2,"explanation":"大量放腹水需同时补充白蛋白（每升腹水补6-8g），防止循环紊乱。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2816","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"自发性细菌性腹膜炎的病原体多为？","options":["金黄色葡萄球菌","肠道革兰阴性菌（大肠埃希菌）","厌氧菌","真菌"],"answer":1,"explanation":"自发性腹膜炎多为肠道革兰阴性菌（大肠埃希菌）移位感染，腹水中性粒细胞>250×10⁶/L可诊断。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2817","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"急性胃炎最常见的病因是？","options":["药物（NSAIDs）和应激、酒精","幽门螺杆菌（急性）","自身免疫","辐射"],"answer":0,"explanation":"急性胃炎常见病因为NSAIDs、酒精、应激（如烧伤、大手术）等急性损伤。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2818","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"慢性肾盂肾炎反复发作的原因不包括？","options":["糖尿病","尿路梗阻","膀胱输尿管反流","长期低蛋白饮食"],"answer":3,"explanation":"尿路梗阻、反流、糖尿病等是慢性肾盂肾炎反复发作的原因；低蛋白饮食与复发无关。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2819","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"尿路感染最常见的致病菌是？","options":["大肠埃希菌","金黄色葡萄球菌","变形杆菌","铜绿假单胞菌"],"answer":0,"explanation":"尿路感染以大肠埃希菌最常见（占70-90%）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2820","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"急性膀胱炎的典型表现是？","options":["高热寒战、腰痛","尿频、尿急、尿痛（无发热或低热）","大量蛋白尿","水肿"],"answer":1,"explanation":"单纯急性膀胱炎仅有膀胱刺激征，全身症状轻；肾盂肾炎伴发热腰痛。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2821","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"慢性肾衰竭分期中，尿毒症期肾小球滤过率（GFR）为？","options":["<60 ml/min","<15 ml/min","<30 ml/min","<90 ml/min"],"answer":1,"explanation":"CKD分期：GFR<15ml/min为尿毒症期（CKD5期），需透析或移植。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2822","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"慢性肾衰竭患者高钾血症的处理不包括？","options":["口服补钾","葡萄糖酸钙静注","葡萄糖+胰岛素","口服降钾树脂"],"answer":0,"explanation":"高钾血症需促进钾转移（钙剂、葡萄糖+胰岛素）和排出（降钾树脂、利尿），禁补钾。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2823","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"血液透析的适应证不包括？","options":["轻度水肿","急性肾衰竭少尿>3天","血钾>6.5mmol/L","尿毒症脑病"],"answer":0,"explanation":"血液透析指征：急性肾衰少尿期长、高钾、心衰、尿毒症脑病等；轻度水肿非透析指征。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2824","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"腹膜透析的主要并发症是？","options":["骨质疏松","贫血","高血压","腹膜炎"],"answer":3,"explanation":"腹膜透析最常见并发症为腹膜炎（透出液浑浊、腹痛）。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2825","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"贫血最常见的类型是？","options":["巨幼细胞贫血","缺铁性贫血","再生障碍性贫血","溶血性贫血"],"answer":1,"explanation":"缺铁性贫血是全球最常见的贫血类型。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2826","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"贫血的诊断标准（成年男性）是？","options":["血红蛋白<120 g/L","血红蛋白<110 g/L","血红蛋白<130 g/L","血红蛋白<100 g/L"],"answer":0,"explanation":"贫血标准：成年男性Hb<120g/L，成年女性（非妊娠）<110g/L，孕妇<100g/L。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2827","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"溶血性贫血的确诊依据是？","options":["红细胞寿命缩短、溶血证据（黄疸、网织红升高）","贫血","白细胞减少","血小板减少"],"answer":0,"explanation":"溶血证据：贫血+黄疸+网织红细胞升高+红细胞寿命缩短，结合溶血相关检查确诊。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2828","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"白细胞减少症的诊断标准是？","options":["白细胞<10×10⁹/L","外周血白细胞<4.0×10⁹/L","白细胞<1×10⁹/L","白细胞>10×10⁹/L"],"answer":1,"explanation":"白细胞减少症：白细胞<4.0×10⁹/L；粒细胞缺乏症：中性粒细胞<0.5×10⁹/L。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2829","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"粒细胞缺乏症的诊断标准是？","options":["中性粒细胞<0.5×10⁹/L","中性粒细胞<1.5×10⁹/L","白细胞<4×10⁹/L","中性粒细胞>5×10⁹/L"],"answer":0,"explanation":"粒细胞缺乏症：中性粒细胞绝对值<0.5×10⁹/L，感染风险极高。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2830","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"过敏性紫癜的主要表现是？","options":["牙龈出血","全身散在瘀斑","双下肢对称性紫癜（可伴关节痛、腹痛、肾损害）","鼻出血"],"answer":2,"explanation":"过敏性紫癜：双下肢对称分布的紫癜，可伴关节（关节型）、腹部（腹型）、肾脏（肾型）损害。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2831","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"过敏性紫癜的发病机制是？","options":["Ⅲ型超敏反应（免疫复合物沉积）","Ⅰ型超敏反应","Ⅱ型超敏反应","Ⅳ型超敏反应"],"answer":0,"explanation":"过敏性紫癜为IgA免疫复合物沉积于小血管（Ⅲ型超敏反应），引起血管炎。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2832","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"弥散性血管内凝血（DIC）的主要表现是？","options":["单纯黄疸","单纯贫血","广泛出血伴微血栓形成（休克、器官损害）","单纯脾大"],"answer":2,"explanation":"DIC：广泛出血（皮肤黏膜、内脏）+微血栓（休克、器官衰竭）+消耗性贫血。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2833","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"DIC的筛查指标不包括？","options":["血小板减少","血小板计数升高","纤维蛋白原降低","D-二聚体升高"],"answer":1,"explanation":"DIC血小板消耗减少、纤维蛋白原降低、D-二聚体升高；血小板升高与DIC相反。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2834","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"输血的适应证不包括？","options":["凝血功能障碍","急性失血（>20%血容量）","严重贫血（Hb<70g/L伴症状）","单纯营养不良"],"answer":3,"explanation":"单纯营养不良非输血适应证；急性大失血、严重贫血、凝血病为适应证。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2835","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"输血最严重的并发症是？","options":["过敏反应","发热反应","溶血性输血反应","循环超负荷"],"answer":2,"explanation":"溶血性输血反应（ABO血型不合）最严重，表现为腰背痛、寒战高热、血红蛋白尿、休克。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2836","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"输血相关发热反应的处理是？","options":["继续快速输血","立即输注肾上腺素","减慢或停止输血、对症处理","利尿"],"answer":2,"explanation":"输血发热反应：减慢或停止输血、解热对症，鉴别溶血反应。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2837","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"成分输血的优点不包括？","options":["增加输血不良反应","一血多用、节约血源","减少不良反应","针对性强"],"answer":0,"explanation":"成分输血针对性强、节约血源、减少不良反应，不增加不良反应。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2838","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"Rh阴性孕妇预防新生儿溶血的措施是？","options":["口服叶酸","分娩Rh阳性胎儿后72小时内注射抗D免疫球蛋白","输血","补铁"],"answer":1,"explanation":"Rh阴性母亲分娩Rh阳性胎儿后72小时内注射抗D免疫球蛋白，防止致敏。","exam":"医疗编","__sub":"内科临床","diff":3,"id":"yl-2839","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"骨髓穿刺最常用的穿刺部位是？","options":["胸骨（首选）","髂前上棘或髂后上棘","腰椎","胫骨"],"answer":1,"explanation":"成人骨髓穿刺首选髂后上棘（或髂前上棘），胸骨为备选（风险高）。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2840","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"霍奇金淋巴瘤的特征性细胞是？","options":["R-S细胞（里-斯细胞）","原始细胞","浆细胞","组织细胞"],"answer":0,"explanation":"霍奇金淋巴瘤病理特征为R-S细胞（镜影细胞）；非霍奇金淋巴瘤无R-S细胞。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2841","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"多发性骨髓瘤的特征性表现是？","options":["脾大","单纯贫血","骨痛、贫血、高钙血症、M蛋白","出血"],"answer":2,"explanation":"多发性骨髓瘤（MM）：骨痛（溶骨性破坏）、贫血、高钙血症、肾功能损害、M蛋白（本周蛋白）。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2842","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"真性红细胞增多症的诊断标准不包括？","options":["JAK2基因突变","红细胞增多（Hb>185/165g/L）","红细胞减少","脾大"],"answer":2,"explanation":"真性红细胞增多症：红细胞增多、JAK2V617F突变、脾大、血栓风险；红细胞减少与诊断相反。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2843","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"脾功能亢进的主要表现是？","options":["发热","单纯贫血","黄疸","脾大伴全血细胞减少"],"answer":3,"explanation":"脾亢：脾大+外周血一系或多系减少+骨髓增生（代偿性）活跃。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2844","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"白细胞淤滞（高白细胞）急性白血病的紧急处理是？","options":["立即输血","白细胞单采术+化疗（羟基脲）","观察","仅补液"],"answer":1,"explanation":"高白细胞白血病（WBC>100×10⁹/L）易致白细胞淤滞，行白细胞单采+羟基脲降负荷。","exam":"医疗编","__sub":"内科临床","diff":3,"id":"yl-2845","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"慢性粒细胞白血病的特征性染色体是？","options":["Ph染色体（t(9;22)）","Ph阴性","21三体","18三体"],"answer":0,"explanation":"CML特征为Ph染色体t(9;22)形成BCR-ABL融合基因，靶向药物为伊马替尼。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2846","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"慢性粒细胞白血病首选的治疗药物是？","options":["干扰素","羟基脲","伊马替尼（酪氨酸激酶抑制剂）","异基因造血干细胞移植"],"answer":2,"explanation":"CML首选伊马替尼（靶向BCR-ABL），羟基脲为降白细胞应急。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2847","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"造血干细胞移植最主要的适应证是？","options":["ITP（初治）","轻度贫血","缺铁性贫血","高危或复发的血液系统恶性肿瘤"],"answer":3,"explanation":"造血干细胞移植用于高危、复发难治的白血病、淋巴瘤、再障等。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2848","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"弥散性血管内凝血（DIC）的基础治疗是？","options":["治疗原发病","肝素抗凝（首要基础）","输血小板","输血"],"answer":0,"explanation":"DIC治疗以去除原发病因为基础，同时抗凝（肝素）、补充凝血因子和血小板。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2849","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"急性早幼粒细胞白血病（APL）的特效治疗是？","options":["干扰素","常规化疗","放疗","全反式维A酸（ATRA）+砷剂"],"answer":3,"explanation":"APL（M3型）用全反式维A酸+亚砷酸（砷剂）诱导分化治疗，治愈率高。","exam":"医疗编","__sub":"内科临床","diff":3,"id":"yl-2850","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"淋巴瘤的确诊依据是？","options":["骨髓穿刺","血常规","淋巴结活检（病理）","影像学"],"answer":2,"explanation":"淋巴瘤确诊依赖淋巴结或受累组织病理活检（金标准）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2851","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"霍奇金淋巴瘤的首选治疗是？","options":["化疗（ABVD方案）±放疗","手术切除","干扰素","观察"],"answer":0,"explanation":"霍奇金淋巴瘤以ABVD方案化疗为主，早期可联合受累野放疗。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2852","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"多发性骨髓瘤的确诊依据是？","options":["骨髓浆细胞≥10%+M蛋白","血常规","尿常规","影像学"],"answer":0,"explanation":"MM诊断：骨髓浆细胞≥10%（或病理证实）+M蛋白+相关器官损害（CRAB）。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2853","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"溶血性输血反应最常见的原因是？","options":["ABO血型不合","Rh血型不合","白细胞抗体","血浆蛋白过敏"],"answer":0,"explanation":"ABO血型不合输血引起急性溶血反应，多因操作差错所致，最严重。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2854","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"大量输血后易发生？","options":["低钙血症和凝血功能障碍","高钙血症","高钾血症（唯一）","碱中毒（必然）"],"answer":0,"explanation":"大量输血（>10U）致枸橼酸中毒（低钙）、稀释性凝血病、低体温、高钾等。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2855","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"血小板输注的适应证不包括？","options":["DIC出血伴血小板减少","血小板<10×10⁹/L（预防出血）","手术前血小板<50×10⁹/L","ITP（一般不预防性输注）"],"answer":3,"explanation":"ITP一般不预防性输注血小板（抗体破坏），仅在出血严重时用。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2856","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"新鲜冰冻血浆（FFP）的主要作用是？","options":["补充血小板","补充红细胞","补充凝血因子","补充白蛋白"],"answer":2,"explanation":"FFP含全部凝血因子，用于凝血因子缺乏或大量输血后凝血病。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2857","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"冷沉淀的主要成分是？","options":["白蛋白","凝血因子Ⅷ、纤维蛋白原、vWF","免疫球蛋白","血小板"],"answer":1,"explanation":"冷沉淀富含Ⅷ因子、纤维蛋白原、vWF，用于血友病甲、纤维蛋白原缺乏。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2858","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"急性白血病缓解后仍需治疗的原因是？","options":["增强体质","预防感染","清除残留白血病细胞（微小残留病）","改善贫血"],"answer":2,"explanation":"缓解后体内仍有微小残留病，需巩固强化（和维持）治疗防止复发。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2859","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"化疗药物外渗的处理是？","options":["热敷","立即停止输注、局部冷敷或按药物要求处理","继续输注","按摩"],"answer":1,"explanation":"化疗药外渗立即停止输注、回抽、局部冷敷（长春碱类热敷）、按药物使用解毒剂。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2860","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肿瘤患者化疗期间白细胞严重减少的处理是？","options":["输注红细胞","立即化疗加量","仅观察","应用G-CSF（升白针）+保护隔离"],"answer":3,"explanation":"化疗后中性粒细胞减少用G-CSF促进恢复，粒细胞缺乏时保护性隔离。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2861","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肿瘤的三级预防中，二级预防是指？","options":["康复治疗","病因预防","早发现、早诊断、早治疗","止痛治疗"],"answer":2,"explanation":"肿瘤二级预防：早发现早诊断早治疗（筛查）；一级为病因预防；三级为康复和姑息治疗。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2862","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肿瘤标志物CEA升高最常见于？","options":["卵巢癌","肝癌（首选）","前列腺癌","结直肠癌（辅助诊断和监测）"],"answer":3,"explanation":"CEA升高常见于结直肠癌、胃癌等腺癌；AFP用于肝癌；PSA用于前列腺癌。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2863","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肿瘤标志物AFP升高最常见于？","options":["原发性肝癌","结直肠癌","肺癌","乳腺癌"],"answer":0,"explanation":"AFP是原发性肝癌的特异性标志物（>400μg/L结合影像可诊断），生殖细胞肿瘤也可升高。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2864","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肿瘤标志物PSA升高提示？","options":["肺癌","肝癌","结直肠癌","前列腺癌"],"answer":3,"explanation":"PSA（前列腺特异性抗原）升高提示前列腺癌（前列腺增生也可轻度升高）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2865","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"癌痛三阶梯止痛的基本原则是？","options":["按需给药","口服给药、按时给药、阶梯给药、个体化、注意细节","肌注为主","疼痛时才给药"],"answer":1,"explanation":"癌痛治疗五原则：口服、按时、阶梯、个体化、注意具体细节。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2866","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"癌痛第一阶梯的药物是？","options":["非甾体抗炎药（布洛芬等）","可待因","吗啡","芬太尼贴剂"],"answer":0,"explanation":"第一阶梯：非甾体抗炎药（轻度疼痛）；第二阶梯：弱阿片类；第三阶梯：强阿片类。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2867","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"癌痛第三阶梯的药物是？","options":["强阿片类（吗啡、芬太尼）","布洛芬","对乙酰氨基酚","曲马多"],"answer":0,"explanation":"第三阶梯用强阿片类（吗啡、羟考酮、芬太尼贴剂），无极量限制（口服为主）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2868","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"吗啡用于癌痛治疗的原则是？","options":["疼痛发作时才给药","按时给药、剂量个体化、口服为主","小剂量固定","肌注为主"],"answer":1,"explanation":"癌痛按时给药（不是疼痛时才给）、口服为主、剂量个体化、及时处理不良反应。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2869","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肿瘤化疗最常见的剂量限制性毒性是？","options":["恶心呕吐","脱发","骨髓抑制","口腔溃疡"],"answer":2,"explanation":"骨髓抑制（白细胞、血小板下降）是多数化疗药的剂量限制性毒性。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2870","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"放射治疗的主要副作用不包括？","options":["骨髓抑制","放射性皮炎","全身性肥胖","放射性肺炎"],"answer":2,"explanation":"放疗副作用：放射性皮炎、黏膜炎、骨髓抑制、放射性肺炎等；全身性肥胖不是放疗副作用。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2871","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"恶性肿瘤最主要的确诊方法是？","options":["肿瘤标志物","影像学检查","病理学检查","临床表现"],"answer":2,"explanation":"病理学检查（活检）是恶性肿瘤确诊的金标准。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2872","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肿瘤的TNM分期中，T代表？","options":["原发肿瘤大小和浸润深度","淋巴结转移","远处转移","组织学分级"],"answer":0,"explanation":"TNM分期：T原发肿瘤、N区域淋巴结、M远处转移。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2873","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肿瘤的TNM分期中，M1代表？","options":["原位癌","无远处转移","淋巴结转移","有远处转移"],"answer":3,"explanation":"M0无远处转移，M1有远处转移（Ⅳ期）。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2874","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"恶性肿瘤的主要转移途径不包括？","options":["淋巴转移","呼吸道飞沫传播","血行转移","直接蔓延、淋巴转移、血行转移、种植转移"],"answer":3,"explanation":"肿瘤转移途径：直接蔓延、淋巴道、血行、种植；呼吸道飞沫为传染病传播途径。","exam":"医疗编","__sub":"内科临床","diff":1,"id":"yl-2875","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"癌性胸腔积液最常见的原因是？","options":["肾病综合征","结核性胸膜炎","心衰","胸膜转移瘤"],"answer":3,"explanation":"癌性胸水多由胸膜转移（肺癌、乳腺癌等）引起，常为血性。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2876","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"上腔静脉综合征最常见的原因是？","options":["肺结核","肺癌（纵隔淋巴结转移）","气胸","胸腔积液"],"answer":1,"explanation":"上腔静脉受压（肺癌纵隔转移、淋巴瘤）致头颈部和上肢静脉回流障碍（面颈肿胀、颈静脉怒张）。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2877","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"脊髓压迫症（肿瘤转移）的首选治疗是？","options":["糖皮质激素+放疗（或手术减压）","化疗","观察","止痛药"],"answer":0,"explanation":"肿瘤脊髓压迫：立即糖皮质激素（减轻水肿）+局部放疗或手术减压，防止瘫痪。","exam":"医疗编","__sub":"内科临床","diff":3,"id":"yl-2878","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"高钙血症（肿瘤相关）的治疗不包括？","options":["双膦酸盐","水化、利尿","补钙","降钙素"],"answer":2,"explanation":"肿瘤高钙血症治疗：水化利尿、双膦酸盐、降钙素；补钙与治疗相反。","exam":"医疗编","__sub":"内科临床","diff":2,"id":"yl-2879","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"肿瘤溶解综合征的典型表现是？","options":["高尿酸、高钾、高磷、低钙","低钾","高钙","低磷"],"answer":0,"explanation":"肿瘤溶解综合征（化疗后大量细胞破坏）：高尿酸、高钾、高磷、低钙，可致急性肾损伤。","exam":"医疗编","__sub":"内科临床","diff":3,"id":"yl-2880","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"腹部损伤空腔脏器破裂的主要表现是？","options":["腹腔内出血（休克）","腹膜炎（腹痛、腹膜刺激征）","血尿","黄疸"],"answer":1,"explanation":"空腔脏器（胃肠）破裂以腹膜炎为主；实质性脏器（肝脾）破裂以腹腔内出血、休克为主。","exam":"医疗编","__sub":"外科临床","diff":1,"id":"yl-2881","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"腹部损伤实质性脏器破裂的主要表现是？","options":["呕血","腹膜炎为主","黄疸","腹腔内出血（面色苍白、休克、腹膜刺激征轻）"],"answer":3,"explanation":"肝脾破裂以内出血为主：面色苍白、脉搏快、血压下降、移动性浊音阳性。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2882","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"腹部损伤诊断性腹腔穿刺的阳性标准是？","options":["无液体抽出","抽出清水样液体","抽出>0.1ml不凝血或胃肠内容物","抽出胆汁（必然）"],"answer":2,"explanation":"诊断性腹腔穿刺抽出0.1ml以上不凝血提示实质性脏器破裂（腹膜脱纤维作用使血不凝）。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2883","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"脾破裂的处理原则是？","options":["确诊后及时手术（脾切除或修补）","保守观察（所有患者）","仅输血","介入栓塞（唯一）"],"answer":0,"explanation":"脾破裂确诊后应及时手术；脾切除后注意接种多价肺炎疫苗（防止OPSI）。","exam":"医疗编","__sub":"外科临床","diff":2,"id":"yl-2884","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿颅内压增高的表现不包括？","options":["头痛、呕吐、视乳头水肿","血压下降","前囟饱满","意识障碍"],"answer":1,"explanation":"颅内压增高：头痛、呕吐、视乳头水肿、前囟饱满、血压升高（代偿）、心率减慢。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2885","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿急性喉炎的主要表现是？","options":["犬吠样咳嗽、声音嘶哑、吸气性喉鸣","单纯咳嗽","喘鸣（哮喘）","吞咽困难"],"answer":0,"explanation":"小儿急性喉炎：犬吠样咳嗽、声音嘶哑、吸气性喉鸣（喉头水肿致气道狭窄）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2886","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿急性喉炎的治疗关键是？","options":["手术","抗生素（唯一）","糖皮质激素（减轻喉头水肿）","雾化生理盐水"],"answer":2,"explanation":"小儿急性喉炎（可致喉梗阻）治疗关键：糖皮质激素（静脉或雾化）减轻水肿，必要时气管切开。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2887","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿支气管哮喘的治疗目标是？","options":["根治（目前不能）","控制症状、维持正常活动、预防发作","长期住院","限制活动"],"answer":1,"explanation":"哮喘治疗目标：控制症状、维持正常活动（包括运动）、预防急性发作、肺功能正常。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2888","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿肥胖症的诊断标准（超过同性别同身高标准体重的）是？","options":["50%","10%","20%以上","5%"],"answer":2,"explanation":"小儿肥胖：体重超过同性别同身高标准体重20%为肥胖（10-20%为超重）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2889","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿遗尿症的诊断年龄是？","options":["7岁以上","3岁以上","5岁以上仍不能自主控制排尿","10岁以上"],"answer":2,"explanation":"遗尿症：5岁以上儿童仍不能自主控制排尿（每周≥2次、持续3个月以上）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2890","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿多动症的主要表现是？","options":["智力低下","注意力缺陷、活动过度、冲动","抽搐","语言障碍"],"answer":1,"explanation":"注意缺陷多动障碍（ADHD）：注意力缺陷、活动过度、冲动，智力正常。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2891","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿孤独症（自闭症）的主要表现是？","options":["抽搐","多动","智力正常（必然）","社交障碍、语言发育障碍、刻板行为"],"answer":3,"explanation":"孤独症谱系障碍：社会交往障碍、语言交流障碍、兴趣狭窄和刻板重复行为。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2892","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿蛋白质-能量营养不良的预防措施是？","options":["仅母乳（长期）","合理喂养（母乳+适时添加辅食）","高糖饮食","不添加辅食"],"answer":1,"explanation":"预防营养不良：提倡母乳喂养、4-6个月适时添加辅食、定期生长发育监测。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2893","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿先天性甲状腺功能减低症的主要表现是？","options":["腹泻","多动","消瘦","智力低下、生长发育迟缓、特殊面容、便秘"],"answer":3,"explanation":"先天性甲减：智力低下、生长发育迟缓、特殊面容（鼻梁低平、舌大外伸）、便秘、黄疸消退延迟。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2894","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"新生儿筛查的疾病不包括？","options":["先天性甲状腺功能减低症","苯丙酮尿症","先天性心脏病（筛查项目之一，但非常规新生儿筛查）","听力障碍"],"answer":2,"explanation":"新生儿筛查：苯丙酮尿症、先天性甲减、听力筛查（部分地区加G6PD缺乏等）；先心病为产前/体格检查发现。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2895","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"苯丙酮尿症的治疗关键是？","options":["手术","高蛋白饮食","输血","低苯丙氨酸饮食（越早越好）"],"answer":3,"explanation":"PKU治疗：尽早低苯丙氨酸饮食（特殊奶粉），终身或长期坚持，防止智力损害。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2896","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿糖尿病以哪种类型为主？","options":["1型糖尿病","2型糖尿病","妊娠糖尿病","特殊类型"],"answer":0,"explanation":"儿童糖尿病以1型为主（胰岛素绝对缺乏），需终身胰岛素治疗。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2897","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿糖尿病酮症酸中毒的治疗关键是？","options":["立即补钾（唯一）","补液+小剂量胰岛素","纠酸（大量碳酸氢钠）","口服降糖药"],"answer":1,"explanation":"儿童DKA：补液（首要）+小剂量胰岛素静滴，谨慎补碱，见尿补钾。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2898","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿呼吸道合胞病毒肺炎的特点是？","options":["咯血","高热持续","脓痰","喘憋明显（毛细支气管炎）"],"answer":3,"explanation":"呼吸道合胞病毒肺炎（毛细支气管炎）：喘憋明显、呼气性喘鸣、肺气肿体征。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2899","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿支原体肺炎的特点是？","options":["肺部湿啰音明显（必然）","脓痰多","刺激性干咳、肺部体征不明显、大环内酯类有效","青霉素有效"],"answer":2,"explanation":"支原体肺炎：刺激性干咳突出、体征轻与症状重不符，首选大环内酯类（阿奇霉素）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2900","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿化脓性脑膜炎最常见的病原体是？","options":["病毒","结核杆菌","脑膜炎奈瑟菌、肺炎链球菌、流感嗜血杆菌","真菌"],"answer":2,"explanation":"小儿化脑以脑膜炎奈瑟菌、肺炎链球菌、流感嗜血杆菌最常见（不同年龄分布不同）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2901","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿化脓性脑膜炎的确诊依据是？","options":["发热","血常规","前囟饱满","脑脊液检查（浑浊、中性粒细胞为主、糖低）"],"answer":3,"explanation":"化脑确诊：脑脊液浑浊、压力高、白细胞>1000×10⁶/L（中性为主）、蛋白高、糖低、培养阳性。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2902","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿化脓性脑膜炎抗生素治疗的原则是？","options":["早期、足量、足疗程、选用易透过血脑屏障的药物","小剂量","单药短程","症状消失即停"],"answer":0,"explanation":"化脑抗生素：早期、足量、足疗程（2-3周）、选用易透过血脑屏障药物（头孢曲松等）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2903","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿结核性脑膜炎的早期表现是？","options":["偏瘫","昏迷","抽搐","性情改变（烦躁、易怒）、低热、盗汗"],"answer":3,"explanation":"结脑早期：性情改变、低热、盗汗、食欲差，中期出现脑膜刺激征和颅神经损害。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2904","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿结核性脑膜炎的治疗关键是？","options":["抗结核药物联合治疗+糖皮质激素","仅对症","仅降颅压","手术"],"answer":0,"explanation":"结脑治疗：早期联合抗结核（异烟肼+利福平+吡嗪酰胺等）+糖皮质激素（减轻炎症）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2905","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿先天性心脏病的预防措施是？","options":["新生儿筛查（唯一）","产后补钙","孕早期避免感染（风疹病毒等）和致畸因素","遗传咨询（唯一）"],"answer":2,"explanation":"预防先心病：孕早期（尤其前3个月）避免风疹病毒感染、药物、放射线等致畸因素。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2906","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿急性肾小球肾炎休息的原则是？","options":["急性期卧床休息2-3周（水肿高血压消退）","立即活动","长期卧床","不休息"],"answer":0,"explanation":"急性肾炎：急性期卧床2-3周（水肿消退、血压正常、肉眼血尿消失），逐渐恢复活动。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2907","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿泌尿系感染的特点是？","options":["均有脓尿（必然）","均有尿频尿急","婴幼儿症状不典型（发热、拒食、哭闹）","均有腰痛"],"answer":2,"explanation":"婴幼儿泌尿系感染症状不典型：发热、拒食、呕吐、哭闹，需尿常规和尿培养确诊。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2908","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿尿路感染的确诊依据是？","options":["血常规","尿常规白细胞增多（唯一）","发热","清洁中段尿培养菌落计数>10⁵/ml"],"answer":3,"explanation":"尿路感染确诊：清洁中段尿培养菌落计数>10⁵/ml（有症状者）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2909","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿贫血的输血指征是？","options":["中度贫血（一律）","所有贫血","轻度贫血","重度贫血（Hb<60g/L）或急性失血"],"answer":3,"explanation":"小儿贫血输血：Hb<60g/L或急性失血、需手术者；轻中度以病因治疗为主。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2910","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿白血病的主要表现是？","options":["黄疸","单纯发热","单纯贫血","贫血、出血、感染、肝脾淋巴结肿大"],"answer":3,"explanation":"小儿急性白血病：贫血、出血、感染、浸润（肝脾淋巴结肿大、骨痛），骨髓原始细胞≥20%。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2911","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿白血病化疗的原则是？","options":["单药长期","早期、联合、足量、间歇、分阶段（诱导缓解→巩固→维持）","症状消失即停","仅支持治疗"],"answer":1,"explanation":"小儿白血病化疗：早期、联合、足量、间歇、分阶段（诱导缓解、巩固强化、维持治疗）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2912","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿风湿热的主要表现不包括？","options":["心脏炎","关节畸形（必然）","环形红斑","皮下结节"],"answer":1,"explanation":"风湿热主要表现：心脏炎、多关节炎（游走性，不留畸形）、舞蹈病、环形红斑、皮下结节。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2913","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿风湿热的预防措施是？","options":["长期用激素","彻底治疗链球菌感染（青霉素）","输血","手术"],"answer":1,"explanation":"风湿热预防：彻底治疗链球菌感染（扁桃体炎等），必要时长期预防性青霉素。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2914","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿川崎病的主要表现不包括？","options":["发热>5天、球结膜充血、口唇皲裂、皮疹、淋巴结肿大、手足硬肿","关节畸形","冠状动脉病变（并发症）","草莓舌"],"answer":1,"explanation":"川崎病：发热>5天、球结膜充血、口唇皲裂草莓舌、多形皮疹、手足硬肿脱皮、颈淋巴结肿大；可致冠脉瘤。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2915","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿川崎病首选的治疗药物是？","options":["阿司匹林+静脉丙种球蛋白","抗生素","激素（唯一）","干扰素"],"answer":0,"explanation":"川崎病：阿司匹林+大剂量静脉丙种球蛋白（IVIG），预防冠状动脉病变。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2916","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿急性上呼吸道感染的处理原则是？","options":["手术","常规抗生素","常规抗病毒（所有）","对症治疗为主（休息、多饮水、退热）"],"answer":3,"explanation":"急性上感多为病毒感染，对症治疗为主（休息、多饮水、退热），不需常规抗生素。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2917","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿急性支气管炎与肺炎的鉴别要点是？","options":["肺炎有固定性湿啰音和气促","咳嗽轻重","发热高低","年龄"],"answer":0,"explanation":"支气管炎与肺炎鉴别：肺炎有气促、固定性中细湿啰音（或影像学实变）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2918","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿腹泻病的护理措施不包括？","options":["观察脱水","调整饮食（继续进食）","臀部护理","禁食（长期）"],"answer":3,"explanation":"腹泻患儿不禁食（继续母乳或易消化饮食），做好臀部护理防尿布皮炎。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2919","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿营养性缺铁性贫血的治疗是？","options":["仅输血","铁剂+维生素C（促进吸收）","仅维生素B12","仅叶酸"],"answer":1,"explanation":"缺铁性贫血：铁剂（餐后服）+维生素C促吸收，血红蛋白正常后继续2-3个月补足储存铁。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2920","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿佝偻病激期的治疗是？","options":["维生素D 2000-4000IU/日（1个月后改预防量）","仅晒太阳","仅补钙","手术"],"answer":0,"explanation":"佝偻病激期：维生素D 2000-4000IU/日口服1个月后改400IU/日维持，同时补钙。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2921","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"新生儿生理性黄疸不需要治疗的原因是？","options":["需要光疗","胆红素极高","需要换血","胆红素水平在安全范围内，可自行消退"],"answer":3,"explanation":"生理性黄疸胆红素<221μmol/L（足月儿），在安全范围内自行消退，不需治疗。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2922","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"新生儿光疗的适应证是？","options":["所有新生儿黄疸","生理性黄疸","病理性黄疸（胆红素超过干预值）","低体重儿（一律）"],"answer":2,"explanation":"光疗用于病理性黄疸（胆红素超过光疗干预值），降低未结合胆红素。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2923","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"新生儿换血疗法的适应证不包括？","options":["胆红素超过换血标准","胆红素脑病早期","溶血性黄疸（重度）","生理性黄疸"],"answer":3,"explanation":"换血用于重度溶血、胆红素超过换血标准、胆红素脑病早期；生理性黄疸不需换血。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2924","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿心肺复苏时，胸外按压与人工呼吸的比例（单人）是？","options":["5:1","15:2","30:2","10:1"],"answer":2,"explanation":"小儿CPR单人施救按压通气比30:2，双人15:2（新生儿3:1）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2925","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿气道异物梗阻（完全性）的急救是？","options":["海姆立克法（腹部冲击）","拍背（唯一）","催吐","饮水"],"answer":0,"explanation":"气道异物梗阻：海姆立克腹部冲击法（1岁以下婴儿用拍背压胸法）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2926","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿溺水的现场急救是？","options":["清理呼吸道、心肺复苏","控水（长时间）","等待","保暖（唯一）"],"answer":0,"explanation":"溺水急救：立即清理口鼻异物、CPR（不主张长时间控水），复苏后注意低体温。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2927","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿一氧化碳中毒的急救是？","options":["脱离环境、吸氧（高压氧）","应用亚甲蓝","洗胃","催吐"],"answer":0,"explanation":"CO中毒：立即脱离环境、吸氧（高压氧最佳），防止脑水肿。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2928","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿有机磷中毒的解救药是？","options":["亚硝酸钠","纳洛酮","美蓝","阿托品+氯解磷定"],"answer":3,"explanation":"小儿有机磷中毒：阿托品（M样症状）+氯解磷定（胆碱酯酶复活剂）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2929","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿药物中毒（误服）的现场处理是？","options":["催吐（清醒者）或洗胃、携带药瓶就医","等待","大量饮水（唯一）","灌肠"],"answer":0,"explanation":"药物中毒：清醒者催吐（腐蚀性药物禁催吐）、洗胃，携带药瓶或呕吐物就医。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2930","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿烫伤的现场处理是？","options":["冷水冲淋（15-30分钟）后就医","涂牙膏","挑破水疱","热敷"],"answer":0,"explanation":"烫伤急救：立即冷水冲淋15-30分钟降温，勿涂牙膏酱油等，勿挑破水疱，及时就医。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2931","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿惊厥持续状态（>30分钟）的危险是？","options":["脑水肿、脑损伤","无危险","仅疲劳","仅脱水"],"answer":0,"explanation":"惊厥持续>30分钟为惊厥持续状态，可致脑水肿、缺氧性脑损伤，需紧急止惊。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2932","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿癫痫持续状态的首选药物是？","options":["卡马西平口服","苯妥英钠口服","地西泮静脉注射","丙戊酸钠口服"],"answer":2,"explanation":"癫痫持续状态首选地西泮0.3-0.5mg/kg缓慢静注，必要时重复。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2933","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿脑瘫的主要表现是？","options":["智力正常（必然）","运动障碍和姿势异常（中枢性）","听力障碍（唯一）","癫痫（唯一）"],"answer":1,"explanation":"脑性瘫痪：中枢性运动障碍和姿势异常（肌张力异常），可伴智力、语言、癫痫等。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2934","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿脑瘫的康复治疗原则是？","options":["等待观察","手术（唯一）","药物（唯一）","早期干预、综合康复（运动训练为主）"],"answer":3,"explanation":"脑瘫康复：早期干预、综合康复（运动疗法、作业疗法、语言训练等），必要时手术矫形。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2935","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿听力障碍的筛查时间是？","options":["3岁","1岁","出生后48小时至出院前（初筛）","6岁"],"answer":2,"explanation":"新生儿听力筛查：出生48小时至出院前初筛，未通过者42天内复筛。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2936","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿视力发育的关键期是？","options":["青春期","学龄期","0-3岁","成年期"],"answer":2,"explanation":"视觉发育关键期0-3岁（敏感期可延至12岁），弱视治疗越早效果越好。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2937","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿弱视的治疗原则是？","options":["早发现早治疗（遮盖疗法等）","等待自愈","手术（唯一）","配镜（唯一）"],"answer":0,"explanation":"弱视治疗：早发现早治疗（配镜+遮盖疗法+视觉训练），12岁前效果较好。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2938","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿近视的预防措施是？","options":["近距离读书","多看电子屏幕","控制用眼时间、增加户外活动（每天2小时）","不检查视力"],"answer":2,"explanation":"近视预防：控制近距离用眼时间、每天户外活动2小时、定期检查视力。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2939","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿脊柱侧弯的筛查方法是？","options":["X线（首选筛查）","体格检查（双肩不等高、弯腰试验）","CT","MRI"],"answer":1,"explanation":"脊柱侧弯筛查：体格检查（双肩不等高、肩胛骨突出、弯腰试验），异常者X线测量Cobb角。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2940","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿维生素A缺乏的主要表现是？","options":["贫血","佝偻病","夜盲、干眼、皮肤角化","出血"],"answer":2,"explanation":"维生素A缺乏：夜盲（最早）、干眼症、角膜软化、皮肤干燥角化。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2941","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿维生素B1缺乏（脚气病）的主要表现是？","options":["夜盲","周围神经炎、心力衰竭（婴儿型）","佝偻病","出血"],"answer":1,"explanation":"维生素B1缺乏：周围神经炎（多发性神经炎）、水肿、心衰（婴儿脚气病）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2942","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿维生素C缺乏（坏血病）的主要表现是？","options":["佝偻病","夜盲","出血倾向、牙龈肿胀、骨膜下出血","脚气病"],"answer":2,"explanation":"维生素C缺乏：牙龈肿胀出血、皮肤瘀点、骨膜下出血（下肢肿痛）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2943","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿锌缺乏的主要表现是？","options":["夜盲","食欲减退、生长发育迟缓、异食癖","佝偻病","出血"],"answer":1,"explanation":"锌缺乏：食欲减退（味觉障碍）、生长发育迟缓、异食癖、免疫力下降。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2944","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿碘缺乏的主要表现是？","options":["出血","夜盲","贫血","甲状腺肿大、智力发育障碍（克汀病）"],"answer":3,"explanation":"碘缺乏：地方性甲状腺肿、克汀病（智力低下、聋哑、瘫痪），食盐加碘预防。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2945","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿肥胖症的预防措施是？","options":["手术","节食（过度）","药物减肥","合理饮食+运动（控制体重增长）"],"answer":3,"explanation":"小儿肥胖预防：合理膳食（控制高糖高脂）、增加运动、定期监测体重，避免过度节食影响发育。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2946","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿性早熟的诊断标准是？","options":["女孩8岁前、男孩9岁前出现第二性征","女孩10岁前","男孩12岁前","任何年龄"],"answer":0,"explanation":"性早熟：女孩8岁前（乳房发育等）、男孩9岁前（睾丸增大等）出现第二性征。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2947","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿性早熟的治疗原则是？","options":["激素替代","观察（所有）","手术（所有）","明确病因（中枢性用GnRH类似物）"],"answer":3,"explanation":"性早熟：明确病因，中枢性（真性）用GnRH类似物抑制发育，外周性治疗原发病。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2948","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿急性中毒的急救原则是？","options":["仅对症","等待观察","立即终止接触毒物、清除未吸收毒物、促进已吸收毒物排出、特效解毒","仅输液"],"answer":2,"explanation":"急性中毒急救：终止接触（脱离环境）、清除毒物（催吐洗胃导尿）、促进排出（利尿透析）、特效解毒剂。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2949","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿误服强酸强碱的处理是？","options":["立即洗胃","立即催吐","禁止催吐洗胃，口服牛奶蛋清中和（弱碱/弱酸）","口服强碱/强酸中和"],"answer":2,"explanation":"强酸强碱中毒禁止催吐洗胃（防穿孔），口服牛奶、蛋清保护黏膜，用弱碱/弱酸中和。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2950","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿一氧化碳中毒迟发性脑病的预防是？","options":["应用抗生素","早期充分氧疗（高压氧）","应用激素（唯一）","输血"],"answer":1,"explanation":"CO中毒迟发性脑病预防：早期足量高压氧治疗（充分氧疗）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2951","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿中暑的处理是？","options":["加盖衣被","应用退热药（唯一）","迅速降温（物理降温）、补液","大量饮用热水"],"answer":2,"explanation":"中暑：迅速脱离高温环境、物理降温（温水擦浴、冰袋）、补液（含盐饮料或静脉）。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2952","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿电击伤的现场急救是？","options":["迅速脱离电源、心肺复苏（必要时）","直接接触患者","注射破伤风抗毒素（唯一）","包扎伤口"],"answer":0,"explanation":"电击伤：先断电（绝缘物挑开电线），评估呼吸心跳，必要时CPR。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2953","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿溺水的预防措施是？","options":["加强看护、游泳安全教育、远离危险水域","禁止游泳（所有）","仅靠救生员","不学习游泳"],"answer":0,"explanation":"溺水预防：加强看护（尤其幼儿）、游泳安全教育、远离无防护水域、学习自救互救。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2954","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿跌落伤的预防措施是？","options":["禁止活动","安装窗户护栏、床护栏、加强看护","仅靠大人抱","不外出"],"answer":1,"explanation":"跌落伤预防：窗户阳台安装护栏、床设护栏、加强看护、地面防滑。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2955","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿误服药物中毒最常见的原因是？","options":["自杀","医源性","药物存放不当（儿童可及）","投毒"],"answer":2,"explanation":"小儿药物中毒多为误服（药物随意放置、儿童好奇误食），应妥善存放药物。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2956","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿疫苗接种的禁忌证不包括？","options":["轻度上呼吸道感染（体温正常）","急性传染病期","严重过敏史","免疫缺陷病"],"answer":0,"explanation":"轻度上感（体温正常、一般情况好）不是接种禁忌；急性传染病、严重过敏、免疫缺陷为禁忌。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2957","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿疫苗接种后发热的处理是？","options":["多饮水、物理降温（一般不需抗生素）","立即抗生素","立即住院","再次接种"],"answer":0,"explanation":"疫苗接种后低热（1-2天）为常见反应，多饮水、物理降温即可，不需抗生素。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2958","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿疫苗接种局部反应的处理是？","options":["热敷（红肿硬结）","冷敷（所有）","切开引流","不处理（所有）"],"answer":0,"explanation":"接种后局部红肿硬结可热敷促进吸收（卡介苗局部反应不热敷，防扩散）。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2959","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿卡介苗接种后局部反应的特点是？","options":["无任何反应","立即化脓（异常）","接种后2-4周局部小溃疡、逐渐结痂（正常反应）","持续流脓（正常）"],"answer":2,"explanation":"卡介苗接种后2-4周局部红肿、小溃疡、结痂（正常反应），不需特殊处理。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2960","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿生长发育监测的频率（1岁内）是？","options":["每月1次","每3个月1次（共4次）","每半年1次","每年1次"],"answer":1,"explanation":"生长发育监测：1岁内每3个月1次，1-2岁每半年1次，3岁后每年1次。","exam":"医疗编","__sub":"儿科临床","diff":1,"id":"yl-2961","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"小儿定期体检的内容不包括？","options":["全身检查","体格测量（体重、身长、头围）","基因检测（常规）","喂养指导"],"answer":2,"explanation":"小儿定期体检：体格测量、全身检查、喂养和发育指导、预防接种；基因检测非常规项目。","exam":"医疗编","__sub":"儿科临床","diff":2,"id":"yl-2962","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行导尿时，发现尿液混浊应","options":["冲洗膀胱","不予处理","留取标本送检并报告医生","拔除尿管"],"answer":2,"explanation":"尿液混浊提示感染或沉淀，应留取标本送检并报告医生。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2963","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行灌肠时，灌肠液温度一般为","options":["45℃","35℃","39～41℃","50℃"],"answer":2,"explanation":"大量不保留灌肠液温39～41℃，降温灌肠28～32℃。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2964","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行冷疗时，时间不宜超过","options":["1小时","30分钟","2小时","10分钟"],"answer":1,"explanation":"冷敷每次不超过30分钟，防止冻伤和反射性不良反应。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2965","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行热疗时，应观察","options":["呼吸","体温","血压","局部皮肤有无烫伤"],"answer":3,"explanation":"热疗应观察局部皮肤颜色、感觉，防止烫伤。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2966","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行乙醇擦浴时，体温降至多少应停止","options":["37℃以下","38℃以下","39℃以下","36℃以下"],"answer":2,"explanation":"乙醇擦浴后30分钟测体温，降至39℃以下可停止。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2967","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行物理降温后，应","options":["30分钟后复测体温","立即测体温","1小时后测","不测"],"answer":0,"explanation":"物理降温后30分钟复测体温，观察降温效果。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2968","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行氧气雾化吸入时，应","options":["指导病人深慢吸气","快速呼吸","屏气","浅呼吸"],"answer":0,"explanation":"氧气雾化应指导病人用嘴深慢吸气，使药液到达下呼吸道。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2969","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行超声雾化吸入时，应","options":["不开水槽开关","先开雾化开关","随意顺序","先开水槽开关，再开雾化开关"],"answer":3,"explanation":"超声雾化先开水槽开关预热，再开雾化开关，防止损坏晶片。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2970","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行注射时，应遵循的原则是","options":["边推边抽","直接推药","先回抽后推药","不回抽"],"answer":2,"explanation":"注射前回抽确认无血，防止药液误入血管。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2971","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行静脉采血时，应","options":["采血后不摇匀","随意采血","不使用采血管","使用真空采血管，按顺序采血"],"answer":3,"explanation":"静脉采血应使用真空采血管，按标准顺序采血并轻摇混匀。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2972","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行血培养采集时，应","options":["餐后采集","任意时间","退热后采集","在发热高峰期采集"],"answer":3,"explanation":"血培养应在寒战、发热高峰期采集，提高阳性率。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2973","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行尿培养采集时，应","options":["混入粪便","留取初段尿","随意留取","留取中段尿"],"answer":3,"explanation":"尿培养应清洁外阴后留取中段尿，防止污染。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2974","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行伤口换药时，应","options":["由外向内","遵循无菌原则，由内向外消毒","不考虑顺序","用酒精冲洗"],"answer":1,"explanation":"伤口换药应遵循无菌原则，消毒由伤口中心向外周环形消毒。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2975","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行伤口换药时，发现伤口红肿应","options":["自行处理","不予处理","用酒精冲洗","报告医生并加强换药"],"answer":3,"explanation":"伤口红肿提示感染，应报告医生并加强换药、必要时做培养。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2976","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行术后引流管护理时，应","options":["不观察","夹闭引流管","保持引流通畅，观察引流液颜色、量、性质","随意放置"],"answer":2,"explanation":"引流管护理应保持通畅、妥善固定、观察引流液颜色量性质并记录。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2977","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行胸腔闭式引流护理时，应","options":["不观察水柱","高于胸腔","随意放置","保持水封瓶低于胸腔出口60cm以上"],"answer":3,"explanation":"胸腔闭式引流瓶应低于胸腔出口60cm以上，观察水柱波动。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2978","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行胃肠减压护理时，应","options":["关闭负压","保持负压吸引通畅","不观察","随意拔管"],"answer":1,"explanation":"胃肠减压应保持负压吸引通畅，观察引流液颜色、量、性质。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2979","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行造口护理时，应","options":["用酒精消毒","不观察","仅更换造口袋","观察造口颜色、形状及周围皮肤"],"answer":3,"explanation":"造口护理应观察造口颜色（红润为正常）、形状、周围皮肤，正确更换造口袋。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2980","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行术后功能锻炼时，应","options":["不锻炼","快速进行","循序渐进，避免过度","过度锻炼"],"answer":2,"explanation":"术后功能锻炼应循序渐进，以不引起明显疼痛为度。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2981","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行康复指导时，应","options":["根据病情制定个体化方案","一律相同","不考虑病情","仅口头"],"answer":0,"explanation":"康复指导应个体化，根据病情、能力制定方案。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2982","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行出院宣教时，应","options":["仅讲解复诊","仅讲解用药","仅讲解饮食","讲解用药、饮食、活动及复诊时间"],"answer":3,"explanation":"出院宣教应全面，包括用药、饮食、活动、复诊及注意事项。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2983","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行入院评估时，应","options":["仅查看病历","仅询问主诉","仅测量生命体征","全面收集健康资料"],"answer":3,"explanation":"入院评估应全面收集健康史、身体状况、心理社会资料等。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2984","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行护理体检时，应","options":["仅查患处","随意检查","按顺序系统检查","不做检查"],"answer":2,"explanation":"护理体检应按顺序系统进行，避免遗漏。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2985","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行护理诊断时，应","options":["仅凭主诉","凭经验","仅凭化验","根据评估资料确定护理问题"],"answer":3,"explanation":"护理诊断基于评估资料，反映病人现存的或潜在的健康问题。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2986","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人制定护理计划时，应","options":["仅写措施","目标模糊","不考虑目标","设定可测量的目标"],"answer":3,"explanation":"护理计划应设定具体、可测量的目标，并制定相应措施。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2987","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人实施护理措施后，应","options":["仅记录","不评价","及时评价效果","仅汇报"],"answer":2,"explanation":"护理程序包括评估、诊断、计划、实施、评价五步，实施后应及时评价。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2988","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行护理记录时，应","options":["遗漏信息","主观猜测","延迟记录","客观、及时、完整、规范"],"answer":3,"explanation":"护理记录应客观、及时、完整、规范，如实反映病情变化和护理措施。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2989","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行交接班时，应","options":["重点交接危重、新入、手术病人","不交接","仅交接物品","仅交接药品"],"answer":0,"explanation":"交接班应重点交接危重、新入、手术及病情变化病人。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2990","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行保护性隔离时，应","options":["增加探视","限制探视，做好环境消毒","不消毒","随意进出"],"answer":1,"explanation":"保护性隔离用于免疫力低下病人，限制探视、做好环境及物品消毒。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2991","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行呼吸道隔离时，应","options":["关闭门窗","随意安置","不隔离","同种病原感染者同室安置"],"answer":3,"explanation":"呼吸道隔离应同种病原同室安置，关闭门窗，做好空气消毒。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2992","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行消化道隔离时，应","options":["随意排放","共用餐具","不消毒","餐具专用，粪便消毒处理"],"answer":3,"explanation":"消化道隔离应餐具专用、分餐，粪便及排泄物消毒后排放。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2993","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行接触隔离时，应","options":["接触病人前后严格手卫生","不洗手","仅戴口罩","仅穿隔离衣"],"answer":0,"explanation":"接触隔离重点是手卫生，接触病人前后严格洗手或手消毒。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2994","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行终末消毒时，应","options":["对出院、死亡病人床单位及病室进行彻底消毒","仅更换床单","不消毒","仅通风"],"answer":0,"explanation":"终末消毒是对出院、转科或死亡病人及其床单位、病室进行的彻底消毒处理。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2995","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行传染病报告时，应","options":["随意上报","按规定时限上报","不报告","延迟报告"],"answer":1,"explanation":"发现传染病应按规定时限（甲类2小时、乙类丙类24小时内）网络直报。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2996","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行职业防护时，应","options":["不防护","仅防护已知感染者","标准预防，视所有病人血液体液为传染性","仅戴口罩"],"answer":2,"explanation":"标准预防要求视所有病人血液、体液、分泌物为潜在传染性，采取相应防护措施。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2997","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行锐器伤处理时，应","options":["用力挤压伤口","从近心端向远心端挤出血液，流动水冲洗，消毒包扎","不处理","仅包扎"],"answer":1,"explanation":"锐器伤应立即从近心端向远心端挤出血液，流动水冲洗，碘伏消毒并报告。","exam":"医疗编","__sub":"护理学","diff":2,"id":"yl-2998","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行化疗防护时，应","options":["不防护","戴双层手套，穿防护服","仅戴口罩","随意操作"],"answer":1,"explanation":"配置化疗药物应戴双层手套、穿防护服、在生物安全柜内操作。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-2999","_shard":"qk-yiliao-05"},{"module":"yiliao","prompt":"为病人进行放射防护时，应","options":["仅距离防护","距离防护、时间防护、屏蔽防护","不防护","仅时间防护"],"answer":1,"explanation":"放射防护三原则：时间、距离、屏蔽防护，减少辐射暴露。","exam":"医疗编","__sub":"护理学","diff":1,"id":"yl-3000","_shard":"qk-yiliao-05"}]);